/* Home Weavers — Supabase Edge Function "hw". GENERATED by tools/build-edge.js from ai-proxy.worker.js; edit that file instead.
   Address: https://<project>.supabase.co/functions/v1/hw   (turn OFF "Verify JWT" for this function:
   Stripe and ShipStation webhooks can't send a Supabase login; admin routes check the admin session themselves.)
   Secrets: Supabase → Edge Functions → Secrets. SUPABASE_URL, SUPABASE_ANON_KEY and SUPABASE_SERVICE_ROLE_KEY are provided by Supabase. */

/* =====================================================================
   Home Weavers — Cloudflare Worker (free plan is enough)
   ---------------------------------------------------------------------
   Keeps every secret key OFF your public website. Routes:

     POST /ai        Claude text for the Marketing studio   (admins only)
     POST /image     AI images via OpenAI (optional)         (admins only)
     POST /welcome   Newsletter welcome email via Brevo (optional)
     POST /snipcart  Snipcart "order.completed" webhook → saves the order (optional)
     POST /checkout/session     Stripe Checkout page for a placed order (shoppers)
     POST /stripe               Stripe webhook → marks the order paid, sends it to ShipStation
     POST /shipstation/push     Send one order to ShipStation again           (admins only)
     POST /shipstation/setup    Register the "order shipped" webhook          (admins only)
     POST /shipstation/webhook  ShipStation SHIP_NOTIFY / FULFILLMENT_SHIPPED → saves carrier + tracking number
     POST /shipstation/sync     Look an order up in ShipStation and save its tracking  (admins only)
     POST /order/cancel         Customer cancels inside the free window: refund + cancel  (order number + email)
     POST /order/placed         Cash-on-delivery order just placed → "we've got your order" email (order number + pay token)
     POST /orders/accept        Accept one order now and send it to ShipStation           (admins only)
     POST /orders/notify        Email the customer that an order was cancelled/refunded/shipped (admins only)
     POST /orders/release       Accept orders whose cancellation window has passed        (scheduled job)
     POST /email/test           Send a sample order email to the signed-in admin           (admins only)
     POST /account/code         Customer sign-in / sign-up: email a 6-digit code
     POST /account/verify       Customer sign-in: check the code → signed 30-day session (no passwords)
     POST /account/google       Customer sign-in with Google: checks Google's signed ID token → the same session
     POST /account/orders       Signed-in customer's orders, profile, saved addresses (Authorization: Bearer <session>)
     POST /account/profile      Signed-in customer: name, phone, saved addresses, email updates on/off
     POST /account/return       Signed-in customer: ask to return a shipped order
     POST /account/signout-all  Signed-in customer: end every session
     POST /account/delete       Signed-in customer: delete profile, addresses and email sign-up (orders are kept)
     POST /order/status         The placing browser checks its order's payment (order number + pay token)
     POST /public/track | /public/cancel-request | /public/contact | /public/subscribe | /public/stock-alert
                                Visitor forms, rate-limited per visitor (IP kept only as a keyed hash)
     POST /account/signout      Ends this customer session on the server too
     POST /admin/health         Which features are set up — never the keys                 (admins only)
     GET  /          Health check: just "ok"

   "Admins only" = the request must carry the signed-in admin's Supabase
   session, and that email must be in the admins table. Anyone else gets 401.

   ----- SECRETS (Worker → Settings → Variables and Secrets) -----
   Required for /ai:
     ANTHROPIC_API_KEY          your Anthropic key (console.anthropic.com)
     SUPABASE_URL               https://xxxx.supabase.co
     SUPABASE_PUBLISHABLE_KEY   sb_publishable_… (the public key from js/config.js)
   Optional:
     ALLOWED_ORIGINS            comma list, e.g. https://rahul26hw.github.io,http://localhost:8080
     OPENAI_API_KEY             enables /image
     SUPABASE_SERVICE_ROLE_KEY  needed by /welcome and /snipcart (secret key — never put it in the website)
     BREVO_API_KEY, FROM_EMAIL, FROM_NAME   enables /welcome
     SNIPCART_SECRET_KEY        enables /snipcart (validates each webhook with Snipcart)
     CLAUDE_EFFORT              low | medium | high (default medium)
   Card payments (Stripe) — also need SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY:
     STRIPE_SECRET_KEY          sk_test_… / sk_live_… (Stripe → Developers → API keys)
     STRIPE_WEBHOOK_SECRET      whsec_… (Stripe → Developers → Webhooks → your endpoint)
   ShipStation (API v1) — also need SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY:
     SHIPSTATION_API_KEY, SHIPSTATION_API_SECRET   (ShipStation → Settings → Account → API Settings)
     SHIPSTATION_WEBHOOK_TOKEN  any long random text; it proves shipment calls come from your ShipStation webhook
   Customer emails (Resend):
     RESEND_API_KEY             re_… (resend.com → API Keys); the sending domain must be verified in Resend
     EMAIL_FROM                 optional, default "Home Weavers <orders@homeweavers.net>"
     EMAIL_REPLY_TO             optional, default the contact email from Admin › Storefront
   Full click-by-click setup: README.md → "AI worker".
   ===================================================================== */

const CLAUDE_MODEL = "claude-opus-5";
const DEFAULT_ORIGINS = ["https://rahul26hw.github.io"]; // add more (e.g. a custom domain) with the ALLOWED_ORIGINS secret

const handler = {
  async fetch(request, env) {
    const url = new URL(request.url);
    const origin = request.headers.get("Origin") || "";
    const cors = corsHeaders(origin, env);

    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    if (request.method === "GET" && url.pathname === "/") return json({ ok: true, service: "home-weavers-worker" }, 200, cors);
    if (request.method !== "POST") return json({ error: "Use POST" }, 405, cors);

    try {
      switch (url.pathname.replace(/\/+$/, "")) {
        case "/ai": return await handleAI(request, env, cors);
        case "/image": return await handleImage(request, env, cors);
        case "/welcome": return await handleWelcome(request, env, cors);
        case "/snipcart": return await handleSnipcart(request, env);
        case "/checkout/session": return await handleCheckoutSession(request, env, cors);
        case "/stripe": return await handleStripeWebhook(request, env);
        case "/shipstation/push": return await handleShipstationPush(request, env, cors);
        case "/shipstation/setup": return await handleShipstationSetup(request, env, cors);
        case "/shipstation/webhook": return await handleShipstationWebhook(request, env);
        case "/shipstation/sync": return await handleShipstationSync(request, env, cors);
        case "/order/cancel": return await handleOrderCancel(request, env, cors);
        case "/order/placed": return await handleOrderPlaced(request, env, cors);
        case "/order/status": return await handleOrderStatus(request, env, cors);
        case "/public/track": case "/public/cancel-request": case "/public/contact": case "/public/subscribe": case "/public/stock-alert":
          return await handlePublic(url.pathname.replace(/\/+$/, ""), request, env, cors);
        case "/account/signout": return await handleAccountSignout(request, env, cors);
        case "/admin/health": {
          const denied = await requireAdmin(request, env);
          if (denied) return json({ error: denied }, 401, cors);
          return json({ ok: true, service: "home-weavers-worker", features: features(env) }, 200, cors);
        }
        case "/orders/accept": return await handleOrderAccept(request, env, cors);
        case "/orders/notify": return await handleOrderNotify(request, env, cors);
        case "/orders/release": return await handleOrderRelease(request, env, cors);
        case "/email/test": return await handleEmailTest(request, env, cors);
        case "/account/code": return await handleAccountCode(request, env, cors);
        case "/account/verify": return await handleAccountVerify(request, env, cors);
        case "/account/google": return await handleAccountGoogle(request, env, cors);
        case "/account/orders": return await handleAccountOrders(request, env, cors);
        case "/account/profile": return await handleAccountProfile(request, env, cors);
        case "/account/return": return await handleAccountReturn(request, env, cors);
        case "/account/signout-all": return await handleAccountSignoutAll(request, env, cors);
        case "/account/delete": return await handleAccountDelete(request, env, cors);
        default: return json({ error: "Not found" }, 404, cors);
      }
    } catch (e) {
      // Details go to the Cloudflare log. Only signed-in admins get them back; shoppers and webhooks get a plain message.
      console.error(url.pathname, e && e.stack ? e.stack : e);
      const adminRoute = ["/ai", "/image", "/shipstation/push", "/shipstation/setup", "/shipstation/sync", "/orders/accept", "/orders/notify", "/email/test", "/admin/health"].includes(url.pathname.replace(/\/+$/, ""));
      return json({ error: adminRoute ? "Worker error: " + (e && e.message ? e.message : "unknown") : "Something went wrong. Please try again in a moment." }, 500, cors);
    }
  },
};

/* ---------------------------------------------------------------- *
 * Helpers
 * ---------------------------------------------------------------- */
function corsHeaders(origin, env) {
  const allowed = (env.ALLOWED_ORIGINS ? env.ALLOWED_ORIGINS.split(",") : DEFAULT_ORIGINS).map((s) => s.trim()).filter(Boolean);
  const h = {
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
    "Access-Control-Max-Age": "86400",
    "Vary": "Origin",
  };
  if (allowed.includes(origin)) h["Access-Control-Allow-Origin"] = origin;
  return h;
}

function json(obj, status = 200, extra = {}) {
  return new Response(JSON.stringify(obj), { status, headers: { "Content-Type": "application/json", ...extra } });
}

async function readJson(request) {
  const text = await request.text();
  if (text.length > 200000) throw new Error("Request too large");
  try { return JSON.parse(text || "{}"); } catch { throw new Error("Invalid JSON"); }
}

/* Confirms the caller is a signed-in Home Weavers admin. */
async function requireAdmin(request, env) {
  if (!env.SUPABASE_URL || !env.SUPABASE_PUBLISHABLE_KEY) return "Worker is missing SUPABASE_URL or SUPABASE_PUBLISHABLE_KEY";
  const auth = request.headers.get("Authorization") || "";
  if (!/^Bearer\s+\S+/.test(auth)) return "Sign in to the admin first";
  const headers = { apikey: env.SUPABASE_PUBLISHABLE_KEY, Authorization: auth, "Content-Type": "application/json" };
  const user = await fetch(env.SUPABASE_URL + "/auth/v1/user", { headers });
  if (!user.ok) return "Your admin session expired — sign in again";
  const check = await fetch(env.SUPABASE_URL + "/rest/v1/rpc/is_admin", { method: "POST", headers, body: "{}" });
  if (!check.ok || (await check.json()) !== true) return "This account isn’t an admin";
  return null;
}

function serviceHeaders(env) {
  const key = env.SUPABASE_SERVICE_ROLE_KEY;
  const h = { apikey: key, "Content-Type": "application/json" };
  // Legacy service_role keys are JWTs and also go in Authorization; new sb_secret_ keys go in apikey only.
  if (/^eyJ/.test(String(key || ""))) h.Authorization = "Bearer " + key;
  return h;
}

/* ---------------------------------------------------------------- *
 * POST /ai  { system, prompt }  →  { text }
 * ---------------------------------------------------------------- */
async function handleAI(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  if (!env.ANTHROPIC_API_KEY) return json({ error: "Worker is missing ANTHROPIC_API_KEY" }, 500, cors);

  const body = await readJson(request);
  const prompt = String(body.prompt || "").slice(0, 20000);
  const system = String(body.system || "").slice(0, 4000);
  if (!prompt) return json({ error: "Missing prompt" }, 400, cors);

  const effort = ["low", "medium", "high"].includes(env.CLAUDE_EFFORT) ? env.CLAUDE_EFFORT : "medium";
  const upstream = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-api-key": env.ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
      // If Claude declines a request, retry it on Anthropic's recommended fallback model.
      "anthropic-beta": "server-side-fallback-2026-07-01",
    },
    body: JSON.stringify({
      model: CLAUDE_MODEL,
      max_tokens: 16000,
      fallbacks: "default",
      output_config: { effort },
      system: system || undefined,
      messages: [{ role: "user", content: prompt }],
    }),
  });

  let data;
  try { data = await upstream.json(); } catch { data = {}; }
  if (!upstream.ok) {
    const msg = (data && data.error && data.error.message) || ("Anthropic API error " + upstream.status);
    return json({ error: msg }, upstream.status === 401 ? 500 : upstream.status, cors);
  }
  if (data.stop_reason === "refusal") return json({ error: "The AI declined this request. Try rewording it." }, 422, cors);

  const text = (data.content || []).filter((b) => b && b.type === "text").map((b) => b.text).join("\n").trim();
  if (!text) return json({ error: data.stop_reason === "max_tokens" ? "The reply was too long — try a smaller request." : "Empty reply from the AI" }, 502, cors);
  return json({ text, stop_reason: data.stop_reason }, 200, cors);
}

/* ---------------------------------------------------------------- *
 * POST /image  { prompt, size }  →  { image: dataURL }
 * ---------------------------------------------------------------- */
async function handleImage(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  if (!env.OPENAI_API_KEY) return json({ error: "Image generation isn’t set up (worker is missing OPENAI_API_KEY)" }, 501, cors);

  const body = await readJson(request);
  const prompt = String(body.prompt || "").slice(0, 4000);
  const size = ["1024x1024", "1536x1024", "1024x1536"].includes(body.size) ? body.size : "1024x1024";
  if (!prompt) return json({ error: "Missing prompt" }, 400, cors);

  const upstream = await fetch("https://api.openai.com/v1/images/generations", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.OPENAI_API_KEY },
    body: JSON.stringify({ model: "gpt-image-1", prompt, size, n: 1 }),
  });
  const data = await upstream.json().catch(() => ({}));
  if (!upstream.ok) return json({ error: (data.error && data.error.message) || "Image API error" }, upstream.status, cors);
  const first = data.data && data.data[0];
  if (first && first.b64_json) return json({ image: "data:image/png;base64," + first.b64_json }, 200, cors);
  if (first && first.url) return json({ url: first.url }, 200, cors);
  return json({ error: "No image returned" }, 502, cors);
}

/* ---------------------------------------------------------------- *
 * POST /welcome  { email }  → sends the welcome code once, right after sign-up.
 * Only emails that subscribed in the last 10 minutes get a message, and the
 * code/offer come from your store data (never from the request).
 * ---------------------------------------------------------------- */
async function handleWelcome(request, env, cors) {
  if (!env.BREVO_API_KEY || !env.FROM_EMAIL || !env.SUPABASE_SERVICE_ROLE_KEY || !env.SUPABASE_URL) return json({ ok: false, error: "Welcome email isn’t set up" }, 501, cors);
  const body = await readJson(request);
  const email = String(body.email || "").trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return json({ ok: false }, 400, cors);

  // Only a fresh sign-up, and only once per address (claimed before sending, so repeats can't slip through).
  const since = new Date(Date.now() - 10 * 60 * 1000).toISOString();
  const claim = await fetch(env.SUPABASE_URL + "/rest/v1/subscribers?email=eq." + encodeURIComponent(email) + "&created_at=gte." + encodeURIComponent(since) + "&welcome_sent_at=is.null",
    { method: "PATCH", headers: Object.assign({ Prefer: "return=representation" }, serviceHeaders(env)), body: JSON.stringify({ welcome_sent_at: new Date().toISOString() }) }).then((r) => r.json()).catch(() => []);
  if (!Array.isArray(claim) || !claim.length) return json({ ok: true }, 200, cors); // quiet: nothing to send

  const store = await fetch(env.SUPABASE_URL + "/rest/v1/store?id=eq.main&select=data", { headers: serviceHeaders(env) }).then((r) => r.json()).catch(() => []);
  const data = (store[0] && store[0].data) || {};
  const brand = (data.brand && data.brand.name) || "Home Weavers";
  const code = String((data.newsletter && data.newsletter.couponCode) || "");
  const promo = (data.promos || []).find((p) => p.active && String(p.code).toUpperCase() === code.toUpperCase());
  const offer = promo ? (promo.type === "percent" ? promo.value + "% off" : "$" + promo.value + " off") : "";
  const site = (data.settings && data.settings.siteUrl) || "";

  const html = `<div style="font-family:Arial,sans-serif;color:#2A2622;max-width:520px;margin:auto;padding:24px">
    <h1 style="font-family:Georgia,serif;font-weight:400">Welcome to ${esc(brand)}</h1>
    <p>Thanks for joining our list. You’ll be first to see new arrivals.</p>
    ${promo ? `<p>Here’s <b>${esc(offer)}</b> your first order:</p><p style="font-size:22px;letter-spacing:2px;background:#EFEAE1;padding:12px 16px;display:inline-block"><b>${esc(promo.code)}</b></p>` : ""}
    ${site ? `<p><a href="${esc(site)}" style="color:#3A5A52">Shop now</a></p>` : ""}
    <p style="color:#6C6359;font-size:12px">You received this because you signed up at ${esc(brand)}.</p></div>`;

  const sent = await fetch("https://api.brevo.com/v3/smtp/email", {
    method: "POST",
    headers: { "api-key": env.BREVO_API_KEY, "Content-Type": "application/json", accept: "application/json" },
    body: JSON.stringify({
      sender: { email: env.FROM_EMAIL, name: env.FROM_NAME || brand },
      to: [{ email }],
      subject: promo ? `Your ${offer} code from ${brand}` : `Welcome to ${brand}`,
      htmlContent: html,
    }),
  });
  return json({ ok: sent.ok }, sent.ok ? 200 : 502, cors);
}

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

/* ---------------------------------------------------------------- *
 * POST /snipcart — Snipcart webhook (Snipcart dashboard → Account → Webhooks).
 * Every call is checked with Snipcart before anything is saved.
 * ---------------------------------------------------------------- */
async function handleSnipcart(request, env) {
  if (!env.SNIPCART_SECRET_KEY || !env.SUPABASE_SERVICE_ROLE_KEY || !env.SUPABASE_URL) return json({ error: "Snipcart webhook isn’t set up" }, 501);
  const token = request.headers.get("X-Snipcart-RequestToken");
  if (!token) return json({ error: "Missing request token" }, 401);
  const check = await fetch("https://app.snipcart.com/api/requestvalidation/" + encodeURIComponent(token), {
    headers: { Accept: "application/json", Authorization: "Basic " + btoa(env.SNIPCART_SECRET_KEY + ":") },
  });
  if (!check.ok) return json({ error: "Request could not be validated with Snipcart" }, 401);

  const body = await readJson(request);
  if (body.eventName !== "order.completed") return json({ ok: true, ignored: body.eventName || "unknown" });
  const o = body.content || {};
  const ship = o.shippingAddress || o.billingAddress || {};
  const number = "SC-" + String(o.invoiceNumber || o.token || Date.now()).replace(/[^A-Za-z0-9-]/g, "").slice(0, 30);

  const order = {
    order_number: number,
    email: String(o.email || "").toLowerCase(),
    name: ship.fullName || ship.name || (o.user && o.user.billingAddressName) || "Snipcart customer",
    phone: ship.phone || null,
    shipping_address: {
      line1: ship.address1 || "", line2: ship.address2 || "", city: ship.city || "",
      state: ship.province || "", zip: ship.postalCode || "", country: ship.country || "",
    },
    subtotal: Number(o.subtotal || o.itemsTotal || 0),
    discount: Number(o.discountsTotal || o.rebateAmount || 0),
    shipping: Number(o.shippingFees || 0),
    tax: Number(o.taxesTotal || o.totalTaxes || 0),
    total: Number(o.grandTotal || o.finalGrandTotal || o.total || 0),
    currency: String(o.currency || "usd").toLowerCase(),
    promo_code: (o.discounts && o.discounts[0] && o.discounts[0].code) || null,
    status: "new",
    payment_status: "paid",
    source: "snipcart",
    external_id: String(o.token || number),
  };

  const ins = await fetch(env.SUPABASE_URL + "/rest/v1/orders?on_conflict=external_id", {
    method: "POST",
    headers: { ...serviceHeaders(env), Prefer: "return=representation,resolution=ignore-duplicates" },
    body: JSON.stringify(order),
  });
  const rows = await ins.json().catch(() => []);
  if (!ins.ok) return json({ error: "Could not save order", detail: rows }, 500);
  if (!Array.isArray(rows) || !rows.length) return json({ ok: true, duplicate: true });

  const items = (o.items || []).map((i) => ({
    order_id: rows[0].id,
    product_id: null,
    sku: String(i.id || ""),
    name: String(i.name || "Item"),
    variant: (i.customFields || []).map((f) => f.value).filter(Boolean).join(" / ") || null,
    unit_price: Number(i.price || 0),
    qty: Math.max(1, Number(i.quantity || 1)),
    line_total: Number(i.totalPrice || (Number(i.price || 0) * Number(i.quantity || 1))),
    image: i.image || null,
  }));
  if (items.length) {
    await fetch(env.SUPABASE_URL + "/rest/v1/order_items", { method: "POST", headers: { ...serviceHeaders(env), Prefer: "return=minimal" }, body: JSON.stringify(items) });
  }
  return json({ ok: true, order: number });
}

/* ================================================================ *
 * Payments (Stripe Checkout) and shipping (ShipStation API v1)
 * ================================================================ */
function features(env) {
  const db = !!(env.SUPABASE_URL && env.SUPABASE_SERVICE_ROLE_KEY);
  const ss = !!(db && env.SHIPSTATION_API_KEY && env.SHIPSTATION_API_SECRET);
  return {
    database: db,
    email: !!env.RESEND_API_KEY,
    ai: !!(env.ANTHROPIC_API_KEY && env.SUPABASE_URL && env.SUPABASE_PUBLISHABLE_KEY),
    stripe: !!(db && env.STRIPE_SECRET_KEY && env.STRIPE_WEBHOOK_SECRET),
    stripeMode: env.STRIPE_SECRET_KEY ? (/^(sk|rk)_live_/.test(env.STRIPE_SECRET_KEY) ? "live" : "test") : null,
    shipstation: ss,
    shipstationWebhook: !!(ss && env.SHIPSTATION_WEBHOOK_TOKEN),
  };
}

const cents = (n) => Math.round(Number(n || 0) * 100);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/* Compares secrets without leaking timing. */
function safeEqual(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

async function db(env, path, init = {}) {
  const res = await fetch(env.SUPABASE_URL + "/rest/v1/" + path, { ...init, headers: { ...serviceHeaders(env), ...(init.headers || {}) } });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  if (!res.ok) throw new Error("Database error " + res.status + ": " + String((data && data.message) || text).slice(0, 200));
  return data;
}

async function loadOrder(env, filter) {
  const rows = await db(env, "orders?" + filter + "&select=*,order_items(*)&limit=1");
  return Array.isArray(rows) && rows[0] ? rows[0] : null;
}

async function patchOrder(env, filter, patch) {
  return db(env, "orders?" + filter, { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify(patch) });
}

/* Minutes a customer can cancel a paid order themselves (Admin › Storefront, default 30). */
async function cancelMinutes(env) {
  const rows = await db(env, "store?id=eq.main&select=data");
  const n = Number(((rows && rows[0] && rows[0].data && rows[0].data.settings) || {}).cancelMinutes);
  return n >= 0 && n <= 1440 ? n : 30;
}

/* ---------------------------------------------------------------- *
 * POST /order/cancel  { order_number, email }  → refunds and cancels inside the free window
 * ---------------------------------------------------------------- */
async function handleOrderCancel(request, env, cors) {
  if (!features(env).database) return json({ error: "Orders aren’t set up yet." }, 501, cors);
  const body = await readJson(request);
  const number = String(body.order_number || "").trim().toUpperCase();
  const email = String(body.email || "").trim().toLowerCase();
  if (!/^[A-Z]{2,4}-\d{1,12}$/.test(number) || !EMAIL_RE.test(email)) return json({ error: "Order not found" }, 404, cors);
  if (await rateLimited(env, request, "cancel", 20, 3600)) return json({ error: "Too many tries. Please wait a while and try again." }, 429, cors);

  const order = await loadOrder(env, "order_number=eq." + encodeURIComponent(number) + "&email=eq." + encodeURIComponent(email));
  if (!order) return json({ error: "Order not found" }, 404, cors);
  // Knowing the email isn't enough: the browser that placed it (pay token), the signed link in the order email,
  // or the customer's signed-in account must ask.
  if (!(await cancelAllowed(request, env, order, body))) return json({ error: "To cancel, use the link in your order email or sign in to your account.", needProof: true }, 403, cors);
  if (order.status === "cancelled") return json({ ok: true, already: true }, 200, cors);

  const minutes = await cancelMinutes(env);
  const started = new Date(order.paid_at || order.created_at).getTime();
  const left = started + minutes * 60000 - Date.now();
  if (order.status !== "new" || left <= 0) {
    return json({ error: "This order can no longer be cancelled here.", tooLate: true, status: order.status }, 409, cors);
  }

  // An unpaid order may still have its payment page open: close it so it can't be paid after cancelling.
  if (order.payment_status === "unpaid" && /^cs_/.test(order.payment_ref || "") && env.STRIPE_SECRET_KEY) {
    await stripe(env, "checkout/sessions/" + encodeURIComponent(order.payment_ref) + "/expire", {}).catch(() => {});
  }
  // Money first: if Stripe fails, the order stays as it was.
  let refunded = false, voided = false;
  if (/^pi_/.test(order.payment_ref || "") && (order.payment_status === "authorized" || order.payment_status === "paid")) {
    if (!env.STRIPE_SECRET_KEY) return json({ error: "Card payments aren’t set up. Please contact us." }, 501, cors);
    if (order.payment_status === "authorized") {
      // Nothing was charged yet: releasing the hold costs no Stripe fee.
      await stripe(env, "payment_intents/" + encodeURIComponent(order.payment_ref) + "/cancel", { cancellation_reason: "requested_by_customer" }, "void-" + order.id);
      voided = true;
    } else {
      await stripe(env, "refunds", { payment_intent: order.payment_ref, reason: "requested_by_customer" }, "refund-" + order.id);
      refunded = true;
    }
  }
  const rows = await patchOrder(env, "id=eq." + order.id + "&status=eq.new", {
    status: "cancelled",
    cancelled_at: new Date().toISOString(),
    payment_status: voided ? "voided" : refunded ? "refunded" : order.payment_status,
    cancel_reason: String(body.reason || "").slice(0, 500) || null,
  });
  if (!Array.isArray(rows) || !rows.length) return json({ error: "This order can no longer be cancelled here.", tooLate: true }, 409, cors);
  await db(env, "promo_redemptions?order_id=eq." + order.id, { method: "DELETE" }).catch(() => {});
  if (order.shipstation_order_id && features(env).shipstation) await pushToShipstation(env, { ...order, status: "cancelled" }).catch(() => {});
  await sendOrderEmail(env, "cancelled", Object.assign({}, order, rows[0]), { refunded, voided, cod: order.payment_method === "cod" });
  return json({ ok: true, refunded, voided }, 200, cors);
}

/* Charges a held card (if any), moves the order to "accepted" and sends it to ShipStation. */
async function acceptOrder(env, order) {
  const patch = { status: "accepted", accepted_at: new Date().toISOString() };
  if (order.payment_status === "authorized") {
    try {
      const pi = await stripe(env, "payment_intents/" + encodeURIComponent(order.payment_ref) + "/capture", {}, "capture-" + order.id);
      if (pi.status !== "succeeded") throw new Error("payment is " + pi.status);
      patch.payment_status = "paid";
    } catch (e) {
      if (!finalCaptureError(e)) {
        // Stripe was busy or unreachable: leave it approved so the next run (or the admin) tries again.
        return { ok: false, retry: true, order_number: order.order_number, error: "Stripe didn’t answer (" + e.message + "). It will be tried again." };
      }
      // The hold can't be charged (declined, expired, card closed…): keep the order out of ShipStation.
      await patchOrder(env, "id=eq." + order.id + "&status=eq.new", {
        payment_status: "failed",
        admin_note: (order.admin_note ? order.admin_note + "\n" : "") + "⚠ Charging the card failed: " + String(e.message).slice(0, 200),
      }).catch(() => {});
      return { ok: false, order_number: order.order_number, error: "Charging the card failed: " + e.message };
    }
  }
  const rows = await patchOrder(env, "id=eq." + order.id + "&status=eq.new", patch);
  if (!Array.isArray(rows) || !rows.length) return { ok: false, skipped: order.order_number };
  const fresh = Object.assign({}, order, rows[0]);
  let shipstation = null;
  if (features(env).shipstation && !fresh.shipstation_order_id) {
    try { shipstation = (await pushToShipstation(env, fresh)).shipstation_order_id; } catch (e) { shipstation = "error: " + e.message; }
  }
  await sendOrderEmail(env, "accepted", fresh);
  return { ok: true, order_number: fresh.order_number, shipstation };
}

/* POST /orders/accept { order_id } — admins only. Accepts now, even if the window hasn't passed. */
async function handleOrderAccept(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  const body = await readJson(request);
  if (!UUID.test(body.order_id || "")) return json({ error: "Missing order" }, 400, cors);
  const order = await loadOrder(env, "id=eq." + body.order_id);
  if (!order) return json({ error: "Order not found" }, 404, cors);
  if (order.status !== "new") return json({ error: "This order was already accepted." }, 409, cors);
  if (!/^(authorized|paid|cod)$/.test(order.payment_status)) return json({ error: "This order isn’t paid, so it can’t be accepted." }, 409, cors);
  const r = await acceptOrder(env, order);
  return json(r, r.retry ? 503 : r.error ? 402 : 200, cors);
}

/* POST /orders/notify { order_id, kind } — admins only. Tells the customer what just happened to their order
   (cancelled, refunded, shipped), because a status changed in the admin never passes through this server. */
const NOTIFY_KINDS = ["cancelled", "refunded", "shipped", "accepted"];
async function handleOrderNotify(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  const body = await readJson(request);
  if (!UUID.test(body.order_id || "")) return json({ error: "Missing order" }, 400, cors);
  const kind = String(body.kind || "");
  if (!NOTIFY_KINDS.includes(kind)) return json({ error: "Unknown message" }, 400, cors);
  const order = await loadOrder(env, "id=eq." + body.order_id);
  if (!order) return json({ error: "Order not found" }, 404, cors);
  const sent = await sendOrderEmail(env, kind, order, {
    cod: order.payment_method === "cod",
    refunded: kind === "refunded",
    voided: kind === "cancelled" && order.payment_status === "voided",
  });
  return json({ ok: !!sent, sent: !!sent, to: order.email }, 200, cors);
}

/* POST /orders/release — the scheduled job (and admins). Accepts every paid order whose window has passed. */
async function handleOrderRelease(request, env, cors) {
  if (!features(env).database) return json({ error: "Not set up" }, 501);
  // The scheduled job calls this without a key: it can only accept orders whose cancellation window has
  // already passed (what would happen anyway) and gets back a bare count. Admins get the details.
  const auth = (request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "");
  let trusted = !!auth && safeEqual(auth, env.SUPABASE_SERVICE_ROLE_KEY || "");
  if (!trusted && auth) trusted = !(await requireAdmin(request, env));
  const minutes = await cancelMinutes(env);
  const cutoff = new Date(Date.now() - minutes * 60000).toISOString();
  const due = await db(env, "orders?status=eq.new&payment_status=in.(authorized,paid,cod)&cancel_requested_at=is.null&review_reason=is.null&paid_at=lt." + encodeURIComponent(cutoff) + "&select=*,order_items(*)&order=paid_at.asc&limit=50");
  const results = [];
  for (const order of Array.isArray(due) ? due : []) results.push(await acceptOrder(env, order));
  const accepted = results.filter((r) => r.ok).length;
  return json(trusted ? { ok: true, accepted, results } : { ok: true, accepted }, 200, cors);
}

async function siteUrl(env) {
  const rows = await db(env, "store?id=eq.main&select=data");
  const s = String((rows && rows[0] && rows[0].data && rows[0].data.settings && rows[0].data.settings.siteUrl) || "").trim();
  if (!/^https:\/\//.test(s)) throw new Error("Set “Live site address” in Admin › Storefront first");
  return s.replace(/\/?$/, "/");
}

/* Stripe takes form encoding: a[b][0][c]=1 */
function formEncode(obj, prefix, out = []) {
  for (const [k, v] of Object.entries(obj)) {
    if (v === undefined || v === null) continue;
    const key = prefix ? `${prefix}[${k}]` : k;
    if (typeof v === "object") formEncode(v, key, out);
    else out.push(encodeURIComponent(key) + "=" + encodeURIComponent(String(v)));
  }
  return out.join("&");
}

async function stripeGet(env, path) {
  const res = await fetch("https://api.stripe.com/v1/" + path, { headers: { Authorization: "Bearer " + env.STRIPE_SECRET_KEY } });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw stripeError(res, data);
  return data;
}

function stripeError(res, data) {
  const e = new Error((data.error && data.error.message) || "Stripe error " + res.status);
  e.status = res.status; e.type = data.error && data.error.type; e.code = data.error && data.error.code;
  return e;
}
/* A capture that can never succeed (declined, or the hold is gone) — anything else is worth retrying. */
function finalCaptureError(e) {
  return e.status === 402 || e.type === "card_error" || e.code === "payment_intent_unexpected_state" || e.code === "charge_expired_for_capture";
}

async function stripe(env, path, params, idempotencyKey) {
  const headers = { Authorization: "Bearer " + env.STRIPE_SECRET_KEY, "Content-Type": "application/x-www-form-urlencoded" };
  if (idempotencyKey) headers["Idempotency-Key"] = idempotencyKey;
  const res = await fetch("https://api.stripe.com/v1/" + path, { method: "POST", headers, body: formEncode(params) });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw stripeError(res, data);
  return data;
}

/* ---------------------------------------------------------------- *
 * POST /checkout/session  { order_number, pay_token }  →  { url }
 * Amounts come from the saved order (already priced by place_order), never from the request.
 * ---------------------------------------------------------------- */
async function handleCheckoutSession(request, env, cors) {
  if (!features(env).stripe) return json({ error: "Card payments aren’t set up yet." }, 501, cors);
  const body = await readJson(request);
  const number = String(body.order_number || "").trim().toUpperCase();
  const token = String(body.pay_token || "").trim();
  if (!/^[A-Z]{2,4}-\d{1,12}$/.test(number) || !UUID.test(token)) return json({ error: "Order not found" }, 404, cors);

  const order = await loadOrder(env, "order_number=eq." + encodeURIComponent(number));
  if (!order || !safeEqual(order.pay_token, token)) return json({ error: "Order not found" }, 404, cors);
  if (order.payment_status === "paid" || order.payment_status === "authorized") return json({ error: "This order is already paid.", paid: true }, 409, cors);
  if (order.payment_method === "cod") return json({ error: "This order is cash on delivery — nothing to pay online." }, 409, cors);
  if (order.status !== "new" || order.payment_status !== "unpaid") return json({ error: "This order can’t be paid online. Please contact us." }, 409, cors);
  if (Date.now() - new Date(order.created_at).getTime() > 7 * 24 * 3600 * 1000) return json({ error: "This order is too old to pay online. Please place it again." }, 409, cors);

  const items = order.order_items || [];
  if (!items.length || items.reduce((s, i) => s + cents(i.unit_price) * i.qty, 0) !== cents(order.subtotal)) {
    return json({ error: "This order’s total doesn’t add up. Please contact us." }, 409, cors);
  }
  // A second tab must not be able to put a second hold on the card: close the previous payment page first.
  if (/^cs_/.test(order.payment_ref || "")) await stripe(env, "checkout/sessions/" + encodeURIComponent(order.payment_ref) + "/expire", {}).catch(() => {});
  const site = await siteUrl(env);
  const orderPage = site + "order/" + encodeURIComponent(order.order_number);
  const currency = order.currency || "usd";

  const params = {
    mode: "payment",
    // Cards only; Apple Pay and Google Pay appear on supported devices as card wallets.
    payment_method_types: ["card"],
    customer_email: order.email,
    client_reference_id: order.order_number,
    success_url: orderPage + "?payment=success",
    cancel_url: orderPage + "?payment=cancelled",
    expires_at: Math.floor(Date.now() / 1000) + 31 * 60,
    metadata: { order_id: order.id, order_number: order.order_number },
    // Authorize now, charge when the order is accepted: a cancellation inside the free window
    // just releases the hold, so neither the customer nor the store pays anything.
    payment_intent_data: { capture_method: "manual", description: "Order " + order.order_number, metadata: { order_id: order.id, order_number: order.order_number } },
    line_items: items.map((i) => ({
      quantity: i.qty,
      price_data: {
        currency,
        unit_amount: cents(i.unit_price),
        product_data: {
          name: (String(i.name) + (i.variant ? " — " + i.variant : "")).slice(0, 250),
          images: /^https:\/\//.test(i.image || "") ? [i.image] : undefined,
          metadata: { sku: i.sku || "" },
        },
      },
    })),
    shipping_options: [{
      shipping_rate_data: {
        type: "fixed_amount",
        display_name: cents(order.shipping) ? "Standard shipping" : "Free shipping",
        fixed_amount: { amount: cents(order.shipping), currency },
      },
    }],
  };
  // Sales tax worked out by place_order, shown as its own line so the Stripe total matches the order.
  if (cents(order.tax) > 0) {
    params.line_items.push({ quantity: 1, price_data: { currency, unit_amount: cents(order.tax), product_data: { name: "Sales tax" } } });
  }
  if (cents(order.discount) > 0) {
    // A one-use coupon for exactly the discount place_order worked out.
    const coupon = await stripe(env, "coupons", {
      amount_off: cents(order.discount), currency, duration: "once", max_redemptions: 1,
      name: ("Discount " + (order.promo_code || "")).trim().slice(0, 40),
    }, "coupon-" + order.id);
    params.discounts = [{ coupon: coupon.id }];
  }

  const session = await stripe(env, "checkout/sessions", params);
  await patchOrder(env, "id=eq." + order.id + "&payment_status=eq.unpaid", { payment_ref: session.id });
  return json({ url: session.url }, 200, cors);
}

/* Stripe-Signature: t=…,v1=… — HMAC-SHA256 of "t.body" with the webhook secret, at most 5 minutes old. */
async function verifyStripe(env, header, payload) {
  const parts = {};
  String(header || "").split(",").forEach((p) => { const i = p.indexOf("="); if (i > 0) (parts[p.slice(0, i)] = parts[p.slice(0, i)] || []).push(p.slice(i + 1)); });
  const t = parts.t && parts.t[0];
  if (!t || !parts.v1 || !(Math.abs(Date.now() / 1000 - Number(t)) <= 300)) return false;
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(env.STRIPE_WEBHOOK_SECRET), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(t + "." + payload));
  const hex = [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, "0")).join("");
  return parts.v1.some((v) => safeEqual(v, hex));
}

/* ---------------------------------------------------------------- *
 * POST /stripe — Stripe webhook. Events: checkout.session.completed,
 * checkout.session.async_payment_succeeded, checkout.session.expired, charge.refunded
 * ---------------------------------------------------------------- */
async function handleStripeWebhook(request, env) {
  if (!features(env).stripe) return json({ error: "Stripe isn’t set up" }, 501);
  const payload = await request.text();
  if (!(await verifyStripe(env, request.headers.get("Stripe-Signature"), payload))) return json({ error: "Bad signature" }, 400);
  const event = JSON.parse(payload);
  const obj = (event.data && event.data.object) || {};
  const orderId = obj.metadata && obj.metadata.order_id;

  if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
    if (!UUID.test(orderId || "")) return json({ ok: true, ignored: "no order" });
    // With authorize-only payments the session says "unpaid" while the card is held, so ask Stripe.
    const pi = obj.payment_intent ? await stripeGet(env, "payment_intents/" + encodeURIComponent(obj.payment_intent)) : null;
    const held = !!pi && pi.status === "requires_capture";
    const captured = pi ? pi.status === "succeeded" : obj.payment_status === "paid";
    if (!held && !captured) return json({ ok: true, waiting: (pi && pi.status) || obj.payment_status });
    const order = await loadOrder(env, "id=eq." + orderId);
    if (!order) return json({ ok: true, ignored: "order missing" });
    const piId = obj.payment_intent || "";
    if (piId && order.payment_ref === piId) return json({ ok: true, duplicate: true });
    // This payment can't belong to the order any more: it was cancelled, or another payment already went through
    // (for example a second tab). Give the money back instead of reviving or double-charging the order.
    if (order.status !== "new" || order.payment_status !== "unpaid") {
      if (piId) {
        try {
          if (held) await stripe(env, "payment_intents/" + encodeURIComponent(piId) + "/cancel", { cancellation_reason: "duplicate" }, "void-extra-" + piId);
          else if (captured) await stripe(env, "refunds", { payment_intent: piId, reason: "duplicate" }, "refund-extra-" + piId);
        } catch (e) { console.error("couldn't release extra payment", piId, e.message); }
        await patchOrder(env, "id=eq." + orderId, { admin_note: (order.admin_note ? order.admin_note + "\n" : "") + "⚠ An extra Stripe payment (" + piId + ") arrived after this order was " + (order.status === "cancelled" ? "cancelled" : "paid") + "; it was " + (held ? "released" : "refunded") + " automatically." }).catch(() => {});
      }
      return json({ ok: true, released: piId || null });
    }
    const amount = held ? pi.amount_capturable : obj.amount_total;
    const mismatch = amount !== cents(order.total);
    const rows = await patchOrder(env, "id=eq." + orderId + "&payment_status=eq.unpaid&status=eq.new", {
      payment_status: held ? "authorized" : "paid",
      paid_at: new Date().toISOString(),
      payment_ref: piId || obj.id,
      payment_livemode: !!obj.livemode,
      // A mismatch keeps the order away from automatic acceptance until a person looks at it.
      review_reason: mismatch ? "Stripe " + (held ? "approved" : "charged") + " $" + (amount / 100).toFixed(2) + " but the order total is $" + Number(order.total).toFixed(2) : null,
      admin_note: mismatch
        ? (order.admin_note ? order.admin_note + "\n" : "") + "⚠ Stripe " + (held ? "authorized" : "charged") + " $" + (amount / 100).toFixed(2) + " but the order total is $" + Number(order.total).toFixed(2) + ". Check before shipping."
        : order.admin_note,
    });
    if (Array.isArray(rows) && rows[0]) {
      Object.assign(order, rows[0]);
      await sendOrderEmail(env, "received", order);
    }
    // The order now waits as "new" until it is accepted (see /orders/accept and /orders/release),
    // so the customer still has their cancellation window before anything reaches the warehouse.
    return json({ ok: true });
  }

  if (event.type === "checkout.session.expired") {
    if (!UUID.test(orderId || "")) return json({ ok: true });
    // Only the latest payment attempt cancels the order; its promo code becomes usable again.
    const rows = await patchOrder(env, "id=eq." + orderId + "&payment_status=eq.unpaid&status=eq.new&payment_ref=eq." + encodeURIComponent(obj.id), { status: "cancelled" });
    const cancelled = Array.isArray(rows) && rows.length > 0;
    if (cancelled) await db(env, "promo_redemptions?order_id=eq." + orderId, { method: "DELETE" });
    return json({ ok: true, cancelled });
  }

  if (event.type === "payment_intent.canceled" && obj.id) {
    // The card hold was released outside our cancel flow (for example it expired after 7 days).
    const rows = await patchOrder(env, "payment_ref=eq." + encodeURIComponent(obj.id) + "&payment_status=eq.authorized", { payment_status: "voided" });
    return json({ ok: true, voided: Array.isArray(rows) ? rows.length : 0 });
  }

  if (event.type === "charge.refunded" && obj.payment_intent && obj.refunded) {
    // Fully refunded in Stripe: stop it from shipping if it hasn't left yet.
    const order = await loadOrder(env, "payment_ref=eq." + encodeURIComponent(obj.payment_intent));
    if (!order || order.payment_status === "refunded") return json({ ok: true });
    const shipped = /^(shipped|delivered)$/.test(order.status);
    const rows = await patchOrder(env, "id=eq." + order.id + "&payment_status=neq.refunded", Object.assign({ payment_status: "refunded" },
      shipped ? { admin_note: (order.admin_note ? order.admin_note + "\n" : "") + "Refunded in Stripe after it shipped." } : { status: "refunded" }));
    if (Array.isArray(rows) && rows[0]) {
      const fresh = Object.assign({}, order, rows[0]);
      if (!shipped && fresh.shipstation_order_id && features(env).shipstation) await pushToShipstation(env, Object.assign({}, fresh, { status: "cancelled" })).catch(() => {});
      await sendOrderEmail(env, "refunded", fresh, { amount: (obj.amount_refunded || 0) / 100 });
    }
    return json({ ok: true });
  }
  return json({ ok: true, ignored: event.type });
}

/* ---------------------------------------------------------------- *
 * ShipStation (API v1)
 * ---------------------------------------------------------------- */
async function shipstation(env, path, init = {}) {
  const res = await fetch(/^https:\/\//.test(path) ? path : "https://ssapi.shipstation.com/" + path, {
    ...init,
    headers: { Authorization: "Basic " + btoa(env.SHIPSTATION_API_KEY + ":" + env.SHIPSTATION_API_SECRET), "Content-Type": "application/json", ...(init.headers || {}) },
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = text; }
  if (!res.ok) throw new Error("ShipStation " + res.status + ": " + String((data && (data.ExceptionMessage || data.Message || data.message)) || text || res.statusText).slice(0, 200));
  return data;
}

function shipstationOrder(order) {
  const a = order.shipping_address || {};
  const cod = order.payment_method === "cod" && order.payment_status !== "paid";
  const paid = order.payment_status === "paid" || cod;
  const items = (order.order_items || []).map((i) => ({
    lineItemKey: i.id,
    sku: i.sku || undefined,
    name: String(i.name || "Item").slice(0, 200),
    imageUrl: /^https:\/\//.test(i.image || "") ? i.image : undefined,
    quantity: i.qty,
    unitPrice: Number(i.unit_price),
    options: i.variant ? [{ name: "Option", value: i.variant }] : [],
  }));
  if (Number(order.discount) > 0) {
    items.push({ lineItemKey: "discount", name: "Discount" + (order.promo_code ? " (" + order.promo_code + ")" : ""), quantity: 1, unitPrice: -Number(order.discount), adjustment: true });
  }
  if (Number(order.cod_fee) > 0) items.push({ lineItemKey: "cod-fee", name: "Cash on delivery fee", quantity: 1, unitPrice: Number(order.cod_fee), adjustment: true });
  const codNote = cod ? "CASH ON DELIVERY — collect " + money(order.total) + " from the customer." : "";
  return {
    orderNumber: order.order_number,
    orderKey: order.id, // ShipStation updates the same order when this is sent again
    orderDate: order.created_at,
    paymentDate: order.paid_at || undefined,
    orderStatus: order.status === "cancelled" ? "cancelled" : paid ? "awaiting_shipment" : "awaiting_payment",
    customerUsername: order.email,
    customerEmail: order.email,
    billTo: { name: order.name },
    shipTo: {
      name: order.name, street1: a.line1 || "", street2: a.line2 || "", city: a.city || "", state: a.state || "",
      postalCode: a.zip || "", country: String(a.country || "US").slice(0, 2).toUpperCase(), phone: order.phone || "", residential: true,
    },
    items,
    amountPaid: paid && !cod ? Number(order.total) : 0,
    paymentMethod: order.payment_method === "cod" ? "Cash on delivery" : "Credit card",
    taxAmount: Number(order.tax || 0),
    shippingAmount: Number(order.shipping || 0),
    customerNotes: order.customer_note || undefined,
    internalNotes: [codNote, order.admin_note].filter(Boolean).join("\n") || undefined,
    advancedOptions: { source: "Home Weavers website" },
  };
}

async function pushToShipstation(env, order) {
  try {
    const res = await shipstation(env, "orders/createorder", { method: "POST", body: JSON.stringify(shipstationOrder(order)) });
    const patch = { shipstation_order_id: String(res.orderId), shipstation_synced_at: new Date().toISOString(), shipstation_error: null };
    await patchOrder(env, "id=eq." + order.id, patch);
    return { ok: true, ...patch };
  } catch (e) {
    await patchOrder(env, "id=eq." + order.id, { shipstation_error: String(e.message).slice(0, 500) }).catch(() => {});
    throw e;
  }
}

/* POST /shipstation/push { order_id } — admins only */
async function handleShipstationPush(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  if (!features(env).shipstation) return json({ error: "ShipStation isn’t set up in the worker." }, 501, cors);
  const body = await readJson(request);
  if (!UUID.test(body.order_id || "")) return json({ error: "Missing order" }, 400, cors);
  const order = await loadOrder(env, "id=eq." + body.order_id);
  if (!order) return json({ error: "Order not found" }, 404, cors);
  // A cancelled order is only sent to cancel its copy in ShipStation.
  if (order.status === "cancelled" && !order.shipstation_order_id) return json({ error: "This order is cancelled and isn’t in ShipStation." }, 409, cors);
  try { return json(await pushToShipstation(env, order), 200, cors); }
  catch (e) { return json({ error: e.message }, 502, cors); }
}

/* POST /shipstation/setup — admins only. Points ShipStation's webhooks at this server (once):
   SHIP_NOTIFY (a label was created) and FULFILLMENT_SHIPPED (an order was marked shipped with a tracking number). */
const SS_EVENTS = ["SHIP_NOTIFY", "FULFILLMENT_SHIPPED", "ORDER_NOTIFY"];
async function handleShipstationSetup(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  if (!features(env).shipstationWebhook) return json({ error: "Add SHIPSTATION_API_KEY, SHIPSTATION_API_SECRET and SHIPSTATION_WEBHOOK_TOKEN to the server secrets first." }, 501, cors);
  // SELF_URL is set when this code runs as a Supabase Edge Function (its public address includes /functions/v1/hw).
  const base = String(env.SELF_URL || new URL(request.url).origin).replace(/\/+$/, "") + "/shipstation/webhook";
  const target = base + "?token=" + encodeURIComponent(env.SHIPSTATION_WEBHOOK_TOKEN);
  const list = await shipstation(env, "webhooks");
  const mine = ((list && list.webhooks) || []).filter((h) => String(h.Url || h.url || "").split("?")[0] === base);
  const added = [];
  for (const h of mine) {
    const ok = (h.Url || h.url) === target && SS_EVENTS.includes(h.HookType || h.hookType);
    if (!ok) await shipstation(env, "webhooks/" + (h.WebHookID || h.webHookId), { method: "DELETE" }).catch(() => {}); // e.g. an old token
  }
  for (const event of SS_EVENTS) {
    if (mine.some((h) => (h.Url || h.url) === target && (h.HookType || h.hookType) === event)) continue;
    const res = await shipstation(env, "webhooks/subscribe", { method: "POST", body: JSON.stringify({ target_url: target, event, store_id: null, friendly_name: "Home Weavers tracking (" + event + ")" }) });
    added.push({ event, id: res && res.id });
  }
  return json({ ok: true, already: added.length === 0, added }, 200, cors);
}

const CARRIERS = { stamps_com: "USPS", usps: "USPS", endicia: "USPS", ups: "UPS", ups_walleted: "UPS", fedex: "FedEx", fedex_walleted: "FedEx", dhl_express: "DHL", dhl_express_worldwide: "DHL", ontrac: "OnTrac" };

/* Saves one ShipStation shipment or fulfillment on our order. `filter` picks the order (by our id or ShipStation's id). */
async function applyShipment(env, filter, s) {
  if (!s || s.voided || !s.trackingNumber) return 0;
  const before = await db(env, "orders?" + filter + "&select=id,status,tracking_number&limit=1");
  const was = Array.isArray(before) && before[0];
  const rows = await patchOrder(env, filter + "&status=in.(new,accepted,packed,shipped)", {
    status: "shipped",
    carrier: CARRIERS[s.carrierCode] || String(s.carrierCode || "").toUpperCase() || null,
    tracking_number: String(s.trackingNumber).slice(0, 100),
    shipped_at: s.shipDate ? new Date(s.shipDate).toISOString() : new Date().toISOString(),
  });
  const updated = Array.isArray(rows) ? rows.length : 0;
  // One "shipped" email per order, and a new one only if the tracking number changes.
  if (updated && was && (was.status !== "shipped" || was.tracking_number !== rows[0].tracking_number)) await sendOrderEmail(env, "shipped", rows[0]);
  return updated;
}

/* A label that was voided (or an order marked unshipped) in ShipStation: put the order back to "accepted"
   here, clear the tracking number, and leave a note. Only ever touches an order we had marked shipped. */
async function unshipOrder(env, filter, s) {
  const before = await db(env, "orders?" + filter + "&select=id,order_number,status,tracking_number,admin_note&limit=1");
  const was = Array.isArray(before) && before[0];
  if (!was || was.status !== "shipped") return 0;
  if (s && s.trackingNumber && was.tracking_number && String(s.trackingNumber) !== String(was.tracking_number)) return 0;
  const note = "⚠ The label" + (was.tracking_number ? " (" + was.tracking_number + ")" : "") + " was voided in ShipStation on " +
    new Date().toISOString().slice(0, 10) + ", so this order went back to Accepted.";
  const rows = await patchOrder(env, filter + "&status=eq.shipped", {
    status: "accepted",
    carrier: null,
    tracking_number: null,
    shipped_at: null,
    admin_note: (was.admin_note ? was.admin_note + "\n" : "") + note,
  });
  return Array.isArray(rows) ? rows.length : 0;
}

/* An order cancelled in ShipStation: cancel it here too, so the shopper's account and the admin agree.
   Only ever moves an order that hasn't shipped and isn't already closed; the database trigger puts the
   stock back, and the shopper gets the cancellation email. */
async function cancelFromShipstation(env, filter, ss) {
  const before = await db(env, "orders?" + filter + "&select=id,order_number,status,admin_note&limit=1");
  const was = Array.isArray(before) && before[0];
  if (!was || !["new", "accepted", "packed"].includes(was.status)) return 0;
  const note = "⚠ Cancelled in ShipStation on " + new Date().toISOString().slice(0, 10) +
    (ss && ss.orderId ? " (ShipStation order " + ss.orderId + ")" : "") + ", so it was cancelled here too.";
  const rows = await patchOrder(env, filter + "&status=in.(new,accepted,packed)", {
    status: "cancelled",
    admin_note: (was.admin_note ? was.admin_note + "\n" : "") + note,
  });
  const updated = Array.isArray(rows) ? rows.length : 0;
  if (updated) await sendOrderEmail(env, "cancelled", rows[0]);
  return updated;
}

/* Our order for a ShipStation record: labels carry our orderKey; fulfillments only carry ShipStation's orderId. */
function shipmentFilter(s) {
  if (UUID.test(s.orderKey || "")) return "id=eq." + s.orderKey;
  if (/^\d+$/.test(String(s.orderId || ""))) return "shipstation_order_id=eq." + s.orderId;
  return null;
}

/* POST /shipstation/webhook?token=… — ShipStation SHIP_NOTIFY / FULFILLMENT_SHIPPED: { resource_url, resource_type } */
async function handleShipstationWebhook(request, env) {
  if (!features(env).shipstationWebhook) return json({ error: "Not set up" }, 501);
  const token = new URL(request.url).searchParams.get("token") || "";
  if (!safeEqual(token, env.SHIPSTATION_WEBHOOK_TOKEN)) return json({ error: "Forbidden" }, 403);
  const body = await readJson(request);
  if (!SS_EVENTS.includes(body.resource_type)) return json({ ok: true, ignored: body.resource_type || "unknown" });
  let resource;
  try { resource = new URL(String(body.resource_url || "")); } catch { return json({ error: "Bad resource_url" }, 400); }
  // The ShipStation key goes with this request, so only ever call ShipStation itself.
  if (resource.protocol !== "https:" || resource.hostname !== "ssapi.shipstation.com") return json({ error: "Bad resource_url" }, 400);

  let updated = 0, page = 1, pages = 1;
  do {
    resource.searchParams.set("page", String(page));
    const data = await shipstation(env, resource.toString());
    pages = Math.min(Number(data && data.pages) || 1, 20);
    for (const s of [].concat((data && data.shipments) || [], (data && data.fulfillments) || [])) {
      const filter = shipmentFilter(s);
      if (!filter) continue;
      updated += s && s.voided ? await unshipOrder(env, filter, s) : await applyShipment(env, filter, s);
    }
    // ORDER_NOTIFY carries the orders themselves. The only change we act on is a cancellation —
    // everything else about an order is ours, not ShipStation's.
    for (const o of (data && data.orders) || []) {
      if (String(o.orderStatus || "").toLowerCase() !== "cancelled") continue;
      const filter = shipmentFilter(o);
      if (!filter) continue;
      updated += await cancelFromShipstation(env, filter, o);
    }
    page++;
  } while (page <= pages);
  return json({ ok: true, updated });
}

/* POST /shipstation/sync { order_id } — admins only. Looks the order up in ShipStation and saves its tracking
   (a safety net if a webhook was missed). */
async function handleShipstationSync(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  if (!features(env).shipstation) return json({ error: "ShipStation isn’t set up on the server." }, 501, cors);
  const body = await readJson(request);
  if (!UUID.test(body.order_id || "")) return json({ error: "Missing order" }, 400, cors);
  const order = await loadOrder(env, "id=eq." + body.order_id);
  if (!order) return json({ error: "Order not found" }, 404, cors);
  if (!order.shipstation_order_id) return json({ error: "This order isn’t in ShipStation yet." }, 409, cors);
  // Cancelling in ShipStation sends no shipment, so check the order's own status first.
  const ssOrder = await shipstation(env, "orders/" + encodeURIComponent(order.shipstation_order_id)).catch(() => null);
  if (ssOrder && String(ssOrder.orderStatus || "").toLowerCase() === "cancelled") {
    const done = await cancelFromShipstation(env, "id=eq." + order.id, ssOrder);
    return json({ ok: true, shipped: false, cancelled: done > 0, status: done > 0 ? "cancelled" : order.status }, 200, cors);
  }
  const num = encodeURIComponent(order.order_number);
  const mine = (s) => !s.voided && s.trackingNumber && (s.orderKey === order.id || String(s.orderId) === String(order.shipstation_order_id));
  const shipments = ((await shipstation(env, "shipments?orderNumber=" + num + "&includeShipmentItems=false")) || {}).shipments || [];
  let found = shipments.filter(mine);
  if (!found.length) found = (((await shipstation(env, "fulfillments?orderNumber=" + num)) || {}).fulfillments || []).filter(mine);
  if (!found.length) {
    // Nothing live in ShipStation any more: if we had it down as shipped, the label was voided or the order unshipped.
    const back = order.status === "shipped" ? await unshipOrder(env, "id=eq." + order.id, null) : 0;
    return json({ ok: true, shipped: false, unshipped: back > 0 }, 200, cors);
  }
  const latest = found.sort((a, b) => String(b.shipDate || "").localeCompare(String(a.shipDate || "")))[0];
  const updated = await applyShipment(env, "id=eq." + order.id, latest);
  const fresh = await loadOrder(env, "id=eq." + order.id);
  return json({ ok: true, shipped: true, updated, carrier: fresh && fresh.carrier, tracking_number: fresh && fresh.tracking_number, status: fresh && fresh.status }, 200, cors);
}

/* ================================================================ *
 * Customer emails (Resend). Secrets: RESEND_API_KEY; optional EMAIL_FROM, EMAIL_REPLY_TO.
 * Every email is best-effort: a failed email is logged and never blocks an order change.
 * ================================================================ */
const EMAIL_FROM_DEFAULT = "Home Weavers <orders@homeweavers.net>";

async function storeData(env) {
  const rows = await db(env, "store?id=eq.main&select=data");
  return (rows && rows[0] && rows[0].data) || {};
}

function trackingLink(carrier, number) {
  if (!number) return "";
  const n = encodeURIComponent(number), c = String(carrier || "").toLowerCase();
  if (/usps|stamps/.test(c)) return "https://tools.usps.com/go/TrackConfirmAction?tLabels=" + n;
  if (/ups/.test(c)) return "https://www.ups.com/track?tracknum=" + n;
  if (/fedex/.test(c)) return "https://www.fedex.com/fedextrack/?trknbr=" + n;
  if (/dhl/.test(c)) return "https://www.dhl.com/us-en/home/tracking.html?tracking-id=" + n;
  return "";
}

const money = (n) => "$" + Number(n || 0).toFixed(2);

function emailLayout(brand, site, title, bodyHtml, why) {
  const b = esc(brand);
  return `<!doctype html><html><body style="margin:0;background:#F7F4EF;font-family:Arial,Helvetica,sans-serif;color:#2A2622">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F7F4EF;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border:1px solid #E6E0D6;border-radius:6px">
<tr><td style="background:#2C463F;padding:18px 24px;border-radius:6px 6px 0 0"><span style="font-family:Georgia,serif;font-size:22px;color:#ffffff">${b}</span></td></tr>
<tr><td style="padding:24px">
<h1 style="font-family:Georgia,serif;font-weight:400;font-size:24px;margin:0 0 14px">${esc(title)}</h1>
${bodyHtml}
</td></tr>
<tr><td style="padding:16px 24px;border-top:1px solid #E6E0D6;font-size:12px;color:#6C6359">
${site ? `<a href="${esc(site)}" style="color:#3A5A52">${esc(site.replace(/^https?:\/\//, "").replace(/\/$/, ""))}</a> · ` : ""}${why ? esc(why) : `You’re getting this email because you placed an order with ${b}.`}
</td></tr></table></td></tr></table></body></html>`;
}

function itemsTable(order) {
  const rows = (order.order_items || []).map((i) =>
    `<tr><td style="padding:6px 0;font-size:14px">${esc(i.name)}${i.variant ? ` <span style="color:#6C6359">(${esc(i.variant)})</span>` : ""} × ${Number(i.qty)}</td>` +
    `<td align="right" style="padding:6px 0;font-size:14px">${money(i.line_total)}</td></tr>`).join("");
  const line = (label, value) => `<tr><td style="padding:4px 0;font-size:14px;color:#6C6359">${label}</td><td align="right" style="padding:4px 0;font-size:14px">${value}</td></tr>`;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #E6E0D6;border-bottom:1px solid #E6E0D6;margin:14px 0">${rows}</table>` +
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0">` +
    line("Subtotal", money(order.subtotal)) +
    (Number(order.discount) > 0 ? line("Discount" + (order.promo_code ? " (" + esc(order.promo_code) + ")" : ""), "−" + money(order.discount)) : "") +
    line("Shipping", Number(order.shipping) > 0 ? money(order.shipping) : "Free") +
    (Number(order.cod_fee) > 0 ? line("Cash on delivery fee", money(order.cod_fee)) : "") +
    (Number(order.tax) > 0 ? line("Sales tax", money(order.tax)) : "") +
    `<tr><td style="padding:6px 0;font-size:15px"><b>Total</b></td><td align="right" style="padding:6px 0;font-size:15px"><b>${money(order.total)}</b></td></tr></table>`;
}

function button(href, label) {
  return `<p style="margin:18px 0"><a href="${esc(href)}" style="display:inline-block;background:#2C463F;color:#ffffff;text-decoration:none;padding:12px 20px;border-radius:4px;font-size:14px;letter-spacing:.04em">${esc(label)}</a></p>`;
}

/* kind: received | accepted | shipped | cancelled | refunded | return */
function buildOrderEmail(kind, order, data, extra = {}) {
  const brand = (data.brand && data.brand.name) || "Home Weavers";
  const site = String((data.settings && data.settings.siteUrl) || "").replace(/\/?$/, "/");
  const minutes = Number((data.settings || {}).cancelMinutes);
  const windowMin = minutes >= 0 && minutes <= 1440 ? minutes : 30;
  const trackUrl = site + "page/track-your-order?order=" + encodeURIComponent(order.order_number) + (extra.cancelToken ? "&c=" + extra.cancelToken : "");
  const first = String(order.name || "").split(" ")[0];
  const hi = `<p style="font-size:15px;line-height:1.6;margin:0 0 10px">Hi ${esc(first || "there")},</p>`;
  const p = (t) => `<p style="font-size:15px;line-height:1.6;margin:0 0 10px">${t}</p>`;
  const num = esc(order.order_number);
  let subject, title, body, text;

  if (kind === "received") {
    subject = `We’ve got your order ${order.order_number}`;
    title = "Thank you for your order";
    body = hi + (order.payment_method === "cod" && order.payment_status !== "paid"
        ? p(`We’ve received order <b>${num}</b>. You’ll pay <b>${money(order.total)}</b> in cash when it’s delivered${Number(order.cod_fee) > 0 ? ` (this includes a ${money(order.cod_fee)} cash-on-delivery fee)` : ""}. Please have the amount ready — the courier may not carry change — and make sure someone over 18 is at the address to take the parcel.`)
        : order.payment_status === "authorized"
        ? p(`We’ve received order <b>${num}</b>. Your card is approved for <b>${money(order.total)}</b>; you’ll only be charged when we start preparing your order.`)
        : p(`Your payment went through and we’ve received order <b>${num}</b>.`)) +
      (windowMin > 0 ? p(`Changed your mind? You can cancel it yourself for the next <b>${windowMin} minutes</b>` + (order.payment_method === "cod" ? "." : order.payment_status === "authorized" ? " and you won’t be charged." : " and get a full refund.") + " After that we start preparing it.") : "") +
      itemsTable(order) + button(trackUrl, windowMin > 0 ? "View or cancel your order" : "View your order");
    text = `Thank you for your order ${order.order_number} (${money(order.total)}).` + (order.payment_method === "cod" ? " Pay in cash when it's delivered." : order.payment_status === "authorized" ? " Your card is approved; you'll be charged when we start preparing it." : "") + (windowMin > 0 ? ` You can cancel within ${windowMin} minutes: ${trackUrl}` : ` Track it: ${trackUrl}`);
  } else if (kind === "accepted") {
    subject = `Your order ${order.order_number} is being prepared`;
    title = "We’re preparing your order";
    body = hi + p(`Good news — order <b>${num}</b> is confirmed and we’re getting it ready to ship. We’ll email you the tracking number as soon as it’s on its way.`) +
      button(trackUrl, "Track your order");
    text = `Order ${order.order_number} is confirmed and being prepared. Track it: ${trackUrl}`;
  } else if (kind === "shipped") {
    const link = trackingLink(order.carrier, order.tracking_number);
    subject = `Your order ${order.order_number} has shipped`;
    title = "Your order is on its way";
    body = hi + p(`Order <b>${num}</b> has shipped${order.carrier ? " with <b>" + esc(order.carrier) + "</b>" : ""}.`) +
      p(`Tracking number: <b>${esc(order.tracking_number || "")}</b>`) +
      (order.payment_method === "cod" && order.payment_status !== "paid" ? p(`Please have <b>${money(order.total)}</b> ready in cash for the delivery.`) : "") +
      (link ? button(link, "Track your package") : button(trackUrl, "Track your order"));
    text = `Order ${order.order_number} has shipped${order.carrier ? " with " + order.carrier : ""}. Tracking: ${order.tracking_number || ""} ${link || trackUrl}`;
  } else if (kind === "cancelled") {
    subject = `Order ${order.order_number} is cancelled`;
    title = "Your order is cancelled";
    body = hi + p(`We’ve cancelled order <b>${num}</b> as you asked.`) +
      (extra.cod ? p(`It was cash on delivery, so there’s nothing to pay.`) : "") +
      (extra.voided ? p(`You haven’t been charged. The temporary hold of <b>${money(order.total)}</b> on your card has been released; depending on your bank it disappears within minutes to a few days.`) : "") +
      (extra.refunded ? p(`Your payment of <b>${money(order.total)}</b> has been refunded to your original payment method. It usually shows up in 5–10 business days.`) : "") +
      p(`We hope to see you again soon.`);
    text = `Order ${order.order_number} is cancelled.` + (extra.voided ? " You haven't been charged; the card hold has been released." : "") + (extra.refunded ? ` ${money(order.total)} has been refunded; allow 5–10 business days.` : "");
  } else if (kind === "refunded") {
    subject = `Refund for order ${order.order_number}`;
    title = "Your refund is on its way";
    body = hi + p(`We’ve refunded ${extra.amount != null ? "<b>" + money(extra.amount) + "</b>" : "your payment"} for order <b>${num}</b> to your original payment method. It usually shows up in 5–10 business days.`);
    text = `We've refunded ${extra.amount != null ? money(extra.amount) : "your payment"} for order ${order.order_number}. Allow 5–10 business days.`;
  } else if (kind === "return") {
    const items = (extra.items || []).map((i) => `<li style="font-size:14px;line-height:1.6">${esc(i)}</li>`).join("");
    subject = `We’ve got your return request for ${order.order_number}`;
    title = "Your return request";
    body = hi + p(`Thanks — we’ve received your request to return items from order <b>${num}</b>:`) +
      (items ? `<ul style="margin:0 0 12px;padding-left:20px">${items}</ul>` : "") +
      p(`We’ll reply within one business day with how to send them back. Please keep them unused and unwashed, with their tags.`) +
      button(site + "account/returns", "See your returns");
    text = `We've received your return request for order ${order.order_number}. We'll reply within one business day with how to send it back.`;
  } else {
    return null;
  }
  return { subject, html: emailLayout(brand, site, title, body), text };
}

async function sendOrderEmail(env, kind, order, extra) {
  if (!env.RESEND_API_KEY || !order || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(order.email || "")) return false;
  try {
    const data = await storeData(env);
    const ex = Object.assign({}, extra || {});
    if (kind === "received" && order.id && !String(order.id).startsWith("test-")) ex.cancelToken = await cancelToken(env, order.id);
    const msg = buildOrderEmail(kind, order, data, ex);
    if (!msg) return false;
    const replyTo = env.EMAIL_REPLY_TO || (data.contact && data.contact.email) || undefined;
    const res = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json", "Idempotency-Key": kind + "-" + order.id },
      body: JSON.stringify({ from: env.EMAIL_FROM || EMAIL_FROM_DEFAULT, to: [order.email], reply_to: replyTo, subject: msg.subject, html: msg.html, text: msg.text }),
    });
    if (!res.ok) console.error("email " + kind + " " + order.order_number + " failed", res.status, (await res.text()).slice(0, 200));
    return res.ok;
  } catch (e) {
    console.error("email " + kind + " failed", e && e.message);
    return false;
  }
}

/* POST /email/test { kind } — admins only. Sends a sample order email to the signed-in admin's own address. */
async function handleEmailTest(request, env, cors) {
  const denied = await requireAdmin(request, env);
  if (denied) return json({ error: denied }, 401, cors);
  if (!env.RESEND_API_KEY) return json({ error: "Add the secret RESEND_API_KEY first." }, 501, cors);
  const who = await fetch(env.SUPABASE_URL + "/auth/v1/user", { headers: { apikey: env.SUPABASE_PUBLISHABLE_KEY, Authorization: request.headers.get("Authorization") } }).then((r) => r.json()).catch(() => ({}));
  if (!who || !who.email) return json({ error: "Couldn’t read your admin email." }, 400, cors);
  const body = await readJson(request);
  const kind = ["received", "accepted", "shipped", "cancelled", "refunded"].includes(body.kind) ? body.kind : "received";
  const sample = {
    id: "test-" + Date.now(), order_number: "HW-TEST", email: who.email, name: "Test Customer",
    subtotal: 64, discount: 0, shipping: 9.95, total: 73.95, carrier: "USPS", tracking_number: "9400100000000000000000",
    order_items: [{ name: "Sample item (this is a test email)", variant: "Blue", qty: 1, line_total: 64 }],
  };
  const sent = await sendOrderEmail(env, kind, sample, { refunded: true, amount: 73.95 });
  return sent ? json({ ok: true, to: who.email, kind }, 200, cors) : json({ error: "Resend didn’t accept the email. Check that homeweavers.net is verified and the key has sending access." }, 502, cors);
}

/* ---------------------------------------------------------------- *
 * Customer accounts — sign in (or sign up) with a code sent by email. No passwords are stored anywhere.
 *   POST /account/code   { email }        → emails a 6-digit code. The same step creates the account for a new email,
 *                                           and the answer is the same either way, so nobody can test who shops here.
 *                                           New emails share a daily cap (LOGIN_NEW_PER_DAY, default 50) so sign-ups can
 *                                           never use up the email quota that order emails need; customers with orders
 *                                           are never capped.
 *   POST /account/verify { email, code }  → { token } — a signed 30-day session
 *   POST /account/orders  Authorization: Bearer <token> → that customer's orders + last address (for checkout)
 * Codes are kept only as keyed hashes in customer_login_codes (service role only) and deleted after a day.
 * ---------------------------------------------------------------- */
// Plain ASCII addresses only (letters, digits and . _ % + ' -), a real domain and a 2–24 letter ending.
const EMAIL_RE = /^[A-Za-z0-9._%+'-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)*\.[A-Za-z]{2,24}$/;
const CODE_MINUTES = 10, CODE_TRIES = 5, SESSION_DAYS = 30;
const CODES_PER_EMAIL_HOUR = 5, CODES_PER_IP_HOUR = 20, NEW_PER_DAY = 50;
const PAID_STATES = "(authorized,paid,refunded,voided,failed,cod)";

const enc = new TextEncoder();
const b64url = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const hexOf = (bytes) => [...new Uint8Array(bytes)].map((b) => b.toString(16).padStart(2, "0")).join("");
async function hmacBytes(key, msg) {
  const k = await crypto.subtle.importKey("raw", enc.encode(key), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return crypto.subtle.sign("HMAC", k, enc.encode(msg));
}
/* Session/code key: CUSTOMER_SESSION_SECRET if set, otherwise derived from the service key (never leaves the server). */
async function accountKey(env) {
  return env.CUSTOMER_SESSION_SECRET || hexOf(await hmacBytes(String(env.SUPABASE_SERVICE_ROLE_KEY || ""), "hw-customer-session-v1"));
}
function clientIp(request) {
  const cf = request.headers.get("cf-connecting-ip");
  if (cf) return cf.trim();
  // The last address is the one our own proxy added; earlier ones can be typed in by the visitor.
  const xff = String(request.headers.get("x-forwarded-for") || "").split(",").map((x) => x.trim()).filter(Boolean);
  return xff.length ? xff[xff.length - 1] : "";
}
async function countRows(env, path) {
  const rows = await db(env, path + "&select=id&limit=100");
  return Array.isArray(rows) ? rows.length : 0;
}

async function handleAccountCode(request, env, cors) {
  if (!features(env).database || !env.RESEND_API_KEY) return json({ error: "Sign-in isn’t available right now. You can still track an order with its number and email." }, 501, cors);
  const body = await readJson(request);
  const email = String(body.email || "").trim().toLowerCase();
  if (!EMAIL_RE.test(email) || email.length > 254) return json({ error: "Enter a valid email address." }, 400, cors);
  const key = await accountKey(env);
  const ipHash = hexOf(await hmacBytes(key, "ip:" + clientIp(request))).slice(0, 32);
  const hourAgo = encodeURIComponent(new Date(Date.now() - 3600000).toISOString());
  const dayAgo = encodeURIComponent(new Date(Date.now() - 86400000).toISOString());
  const cap = Number(env.LOGIN_NEW_PER_DAY) > 0 ? Number(env.LOGIN_NEW_PER_DAY) : NEW_PER_DAY;

  // Independent look-ups run together (each is a round trip to the database).
  const [, byIp, byEmail, known, recentNew, data] = await Promise.all([
    db(env, "customer_login_codes?created_at=lt." + dayAgo, { method: "DELETE" }).catch(() => {}),
    countRows(env, "customer_login_codes?ip_hash=eq." + ipHash + "&created_at=gt." + hourAgo),
    countRows(env, "customer_login_codes?email=eq." + encodeURIComponent(email) + "&created_at=gt." + hourAgo),
    db(env, "orders?email=eq." + encodeURIComponent(email) + "&payment_status=in." + PAID_STATES + "&select=id&limit=1"),
    db(env, "customer_login_codes?new_customer=eq.true&created_at=gt." + dayAgo + "&select=id&limit=" + cap),
    storeData(env),
  ]);
  if (byIp >= CODES_PER_IP_HOUR || byEmail >= CODES_PER_EMAIL_HOUR) {
    return json({ error: "Too many codes asked for. Please try again in an hour." }, 429, cors);
  }
  const isCustomer = Array.isArray(known) && known.length > 0;
  // Past the daily sign-up cap, answer exactly as usual but send nothing: the reply never reveals who is a customer.
  if (!isCustomer && Array.isArray(recentNew) && recentNew.length >= cap) return json({ ok: true }, 200, cors);

  const code = String(crypto.getRandomValues(new Uint32Array(1))[0] % 1000000).padStart(6, "0");
  const id = crypto.randomUUID();
  const brand = (data.brand && data.brand.name) || "Home Weavers";
  const site = String((data.settings && data.settings.siteUrl) || "").replace(/\/?$/, "/");
  const html = emailLayout(brand, site, "Your sign-in code",
    `<p style="font-size:15px;line-height:1.6;margin:0 0 10px">Use this code to sign in to your ${esc(brand)} account${isCustomer ? " and see your orders" : ""}:</p>` +
    `<p style="font-size:32px;letter-spacing:.3em;font-weight:bold;margin:16px 0;font-family:Georgia,serif">${code}</p>` +
    `<p style="font-size:14px;line-height:1.6;color:#6C6359;margin:0">It works for ${CODE_MINUTES} minutes. If you didn’t ask for it, you can ignore this email — nobody can sign in without the code.</p>`,
    "You’re getting this email because someone asked to sign in to " + brand + " with this address.");
  // Save the code and send the email together.
  const [, res] = await Promise.all([
    db(env, "customer_login_codes", {
      method: "POST",
      body: JSON.stringify({
        id, email, ip_hash: ipHash, new_customer: !isCustomer,
        code_hash: hexOf(await hmacBytes(key, "code:" + email + ":" + code)),
        expires_at: new Date(Date.now() + CODE_MINUTES * 60000).toISOString(),
      }),
    }),
    fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json", "Idempotency-Key": "login-" + id },
      body: JSON.stringify({ from: env.EMAIL_FROM || EMAIL_FROM_DEFAULT, to: [email], subject: `${code} is your ${brand} sign-in code`, html, text: `Your ${brand} sign-in code is ${code}. It works for ${CODE_MINUTES} minutes. If you didn't ask for it, ignore this email.` }),
    }),
  ]);
  if (!res.ok) console.error("login email failed", res.status, (await res.text()).slice(0, 200));
  return json({ ok: true }, 200, cors);
}

async function handleAccountVerify(request, env, cors) {
  if (!features(env).database) return json({ error: "Sign-in isn’t available right now." }, 501, cors);
  const body = await readJson(request);
  const email = String(body.email || "").trim().toLowerCase();
  const code = String(body.code || "").replace(/\s+/g, "");
  const wrong = (extra) => json(Object.assign({ error: "That code isn’t right or has expired. Check it, or ask for a new one." }, extra || {}), 400, cors);
  if (!EMAIL_RE.test(email) || !/^\d{6}$/.test(code)) return wrong();
  const now = new Date().toISOString();
  // At most 20 wrong codes per email per day, across all codes.
  const today = await db(env, "customer_login_codes?email=eq." + encodeURIComponent(email) + "&created_at=gt." + encodeURIComponent(new Date(Date.now() - 86400000).toISOString()) + "&select=attempts&limit=100");
  if (Array.isArray(today) && today.reduce((n, x) => n + (Number(x.attempts) || 0), 0) >= 20) return json({ error: "Too many tries today. Please try again tomorrow." }, 429, cors);
  const rows = await db(env, "customer_login_codes?email=eq." + encodeURIComponent(email) + "&used_at=is.null&expires_at=gt." + encodeURIComponent(now) + "&select=id,code_hash,attempts&order=created_at.desc&limit=1");
  const row = Array.isArray(rows) && rows[0];
  if (!row) return wrong();
  if (row.attempts >= CODE_TRIES) return json({ error: "Too many tries. Ask for a new code." }, 429, cors);
  // Count the try first (only if nobody else counted it meanwhile), then compare.
  const bumped = await db(env, "customer_login_codes?id=eq." + row.id + "&attempts=eq." + row.attempts, { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify({ attempts: row.attempts + 1 }) });
  if (!Array.isArray(bumped) || !bumped.length) return wrong();
  const key = await accountKey(env);
  if (!safeEqual(row.code_hash, hexOf(await hmacBytes(key, "code:" + email + ":" + code)))) return wrong({ triesLeft: Math.max(0, CODE_TRIES - row.attempts - 1) });
  const used = await db(env, "customer_login_codes?id=eq." + row.id + "&used_at=is.null", { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify({ used_at: now }) });
  if (!Array.isArray(used) || !used.length) return wrong();
  return json(Object.assign({ ok: true }, await issueSession(env, email)), 200, cors);
}

/* A signed 30-day customer session for an email that has just proved it's theirs. */
async function issueSession(env, email) {
  const exp = Math.floor(Date.now() / 1000) + SESSION_DAYS * 86400;
  const payload = b64url(enc.encode(JSON.stringify({ e: email, x: exp, i: Date.now(), n: b64url(crypto.getRandomValues(new Uint8Array(9))) })));
  const token = payload + "." + b64url(await hmacBytes(await accountKey(env), "session:" + payload));
  return { token, email, expires: new Date(exp * 1000).toISOString() };
}

/* ---------------------------------------------------------------- *
 * POST /account/google { id_token, nonce } — "Continue with Google".
 * The site sends the shopper to Google's own page (OpenID Connect, no Google script on our pages) and gets back an
 * ID token signed by Google. Here we check Google's signature, that the token was made for OUR client ID, that it's
 * fresh, that Google verified the email, and that it carries the one-time nonce this browser started with.
 * The client ID is public: Admin › Storefront › Customer accounts (or the secret GOOGLE_CLIENT_ID).
 * ---------------------------------------------------------------- */
const GOOGLE_ISSUERS = ["accounts.google.com", "https://accounts.google.com"];
const GOOGLE_CERTS = "https://www.googleapis.com/oauth2/v3/certs";
let googleKeyCache = { at: 0, keys: [] };
const b64urlBytes = (str) => {
  const s64 = String(str).replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(s64 + "===".slice((s64.length + 3) % 4)), (c) => c.charCodeAt(0));
};
const b64urlJson = (str) => JSON.parse(new TextDecoder().decode(b64urlBytes(str)));

async function googleKeys(force) {
  if (!force && googleKeyCache.keys.length && Date.now() - googleKeyCache.at < 3600000) return googleKeyCache.keys;
  const res = await fetch(GOOGLE_CERTS);
  if (!res.ok) throw new Error("Couldn’t reach Google. Please try again.");
  const data = await res.json();
  googleKeyCache = { at: Date.now(), keys: Array.isArray(data.keys) ? data.keys : [] };
  return googleKeyCache.keys;
}

/* Returns the token's claims, or throws with a shopper-friendly message. */
async function verifyGoogleToken(jwt, clientId) {
  const bad = new Error("Google sign-in didn’t work. Please try again.");
  const parts = String(jwt || "").split(".");
  if (parts.length !== 3 || parts.some((x) => !/^[A-Za-z0-9_-]+$/.test(x))) throw bad;
  let header, claims;
  try { header = b64urlJson(parts[0]); claims = b64urlJson(parts[1]); } catch { throw bad; }
  if (!header || header.alg !== "RS256" || !header.kid) throw bad;
  let jwk = (await googleKeys()).find((k) => k.kid === header.kid);
  if (!jwk) jwk = (await googleKeys(true)).find((k) => k.kid === header.kid); // Google rotates keys
  if (!jwk || jwk.kty !== "RSA") throw bad;
  const key = await crypto.subtle.importKey("jwk", { kty: "RSA", n: jwk.n, e: jwk.e, alg: "RS256", ext: true }, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"]);
  const valid = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64urlBytes(parts[2]), enc.encode(parts[0] + "." + parts[1]));
  if (!valid) throw bad;
  const now = Math.floor(Date.now() / 1000);
  const aud = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
  if (!GOOGLE_ISSUERS.includes(claims.iss) || !aud.includes(clientId) || (claims.azp && claims.azp !== clientId)) throw bad;
  if (!(Number(claims.exp) > now - 60) || Number(claims.iat) > now + 300) throw new Error("That Google sign-in has expired. Please try again.");
  return claims;
}

async function handleAccountGoogle(request, env, cors) {
  if (!features(env).database) return json({ error: "Sign-in isn’t available right now." }, 501, cors);
  const data = await storeData(env);
  const clientId = String(env.GOOGLE_CLIENT_ID || (data.settings && data.settings.googleClientId) || "").trim();
  if (!/^[\w.-]+\.apps\.googleusercontent\.com$/.test(clientId)) return json({ error: "Google sign-in isn’t set up yet. Use your email instead." }, 501, cors);
  const body = await readJson(request);
  let claims;
  try { claims = await verifyGoogleToken(body.id_token, clientId); } catch (e) { return json({ error: e.message }, 401, cors); }
  const nonce = String(body.nonce || "");
  if (!/^[A-Za-z0-9_-]{16,128}$/.test(nonce) || !safeEqual(String(claims.nonce || ""), nonce)) return json({ error: "Google sign-in didn’t work. Please try again." }, 401, cors);
  const email = String(claims.email || "").trim().toLowerCase();
  if (!EMAIL_RE.test(email) || email.length > 254) return json({ error: "Google didn’t share an email address." }, 400, cors);
  if (claims.email_verified !== true && claims.email_verified !== "true") return json({ error: "Your Google email isn’t verified yet. Use your email instead." }, 400, cors);
  // First Google sign-in: fill in an empty name from the Google profile (never overwrite what the customer typed).
  const rows = await db(env, "customer_profiles?email=eq." + encodeURIComponent(email) + "&select=first_name,last_name&limit=1");
  const cur = Array.isArray(rows) && rows[0];
  if (!cur || (!cur.first_name && !cur.last_name)) {
    const first = str(claims.given_name, 60), last = str(claims.family_name, 60);
    if (first || last) {
      await db(env, "customer_profiles?on_conflict=email", { method: "POST", headers: { Prefer: "resolution=merge-duplicates" }, body: JSON.stringify({ email, first_name: first || null, last_name: last || null }) }).catch(() => {});
    }
  }
  return json(Object.assign({ ok: true, via: "google" }, await issueSession(env, email)), 200, cors);
}

/* A valid customer session → { email, profile } (profile may be null), or null.
   Sessions issued before the profile's signed_out_at ("Sign out on all devices", "Delete account") are refused. */
async function customerSession(request, env) {
  const m = /^Bearer\s+([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]+)$/.exec(request.headers.get("Authorization") || "");
  if (!m) return null;
  const expect = b64url(await hmacBytes(await accountKey(env), "session:" + m[1]));
  if (!safeEqual(expect, m[2])) return null;
  let p;
  try { p = JSON.parse(atob(m[1].replace(/-/g, "+").replace(/_/g, "/"))); } catch { return null; }
  if (!p || !EMAIL_RE.test(p.e || "") || !(Number(p.x) * 1000 > Date.now())) return null;
  const [rows, revoked] = await Promise.all([
    db(env, "customer_profiles?email=eq." + encodeURIComponent(p.e) + "&select=first_name,last_name,phone,addresses,signed_out_at&limit=1"),
    p.n ? db(env, "customer_revoked?n=eq." + encodeURIComponent(String(p.n)) + "&select=n&limit=1") : [],
  ]);
  if (Array.isArray(revoked) && revoked.length) return null; // signed out
  const profile = Array.isArray(rows) && rows[0] ? rows[0] : null;
  if (profile && profile.signed_out_at && !(Number(p.i || 0) > Date.parse(profile.signed_out_at))) return null;
  return { email: p.e, profile, nonce: String(p.n || ""), exp: Number(p.x) };
}
const signedOut = (cors) => json({ error: "Please sign in again.", signedOut: true }, 401, cors);

function publicProfile(profile) {
  const pr = profile || {};
  return { first_name: pr.first_name || "", last_name: pr.last_name || "", phone: pr.phone || "", addresses: Array.isArray(pr.addresses) ? pr.addresses : [] };
}

/* POST /account/orders — everything the account panel shows: orders, profile, saved addresses, email updates. */
async function handleAccountOrders(request, env, cors) {
  if (!features(env).database) return json({ error: "Sign-in isn’t available right now." }, 501, cors);
  const s = await customerSession(request, env);
  if (!s) return signedOut(cors);
  // Only what the customer needs to see: no internal ids, notes, payment references or tokens.
  const cols = "order_number,created_at,paid_at,accepted_at,shipped_at,cancelled_at,status,payment_status,payment_method,cod_fee,subtotal,discount,shipping,tax,total,promo_code," +
    "carrier,tracking_number,cancel_requested_at,return_requested_at,return_reason,name,phone,shipping_address,order_items(name,variant,qty,unit_price,image,line_total)";
  const [rows, subs] = await Promise.all([
    db(env, "orders?email=eq." + encodeURIComponent(s.email) + "&payment_status=in." + PAID_STATES + "&select=" + cols + "&order=created_at.desc&limit=50"),
    db(env, "subscribers?email=eq." + encodeURIComponent(s.email) + "&select=id&limit=1"),
  ]);
  const list = Array.isArray(rows) ? rows : [];
  const last = list[0];
  const lastAddress = last ? { name: last.name || "", phone: last.phone || "", address: last.shipping_address || {} } : null;
  const orders = list.map((o) => {
    const c = Object.assign({}, o, { items: o.order_items || [] });
    delete c.order_items;
    return c;
  });
  return json({ ok: true, email: s.email, orders, profile: publicProfile(s.profile), lastAddress, subscribed: Array.isArray(subs) && subs.length > 0 }, 200, cors);
}

const US_STATES = "AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY".split(" ");
const str = (v, max) => String(v == null ? "" : v).replace(/[\u0000-\u001f\u007f]/g, " ").trim().slice(0, max);

/* One saved address, checked and trimmed; throws a shopper-friendly message. */
function cleanAddress(a, i) {
  const out = {
    id: /^[A-Za-z0-9-]{1,40}$/.test(String(a && a.id || "")) ? String(a.id) : crypto.randomUUID(),
    label: str(a && a.label, 40),
    name: str(a && a.name, 120), phone: str(a && a.phone, 40),
    line1: str(a && a.line1, 200), line2: str(a && a.line2, 200), city: str(a && a.city, 100),
    state: str(a && a.state, 2).toUpperCase(), zip: str(a && a.zip, 10), country: "US",
    is_default: !!(a && a.is_default),
  };
  const n = "Address " + (i + 1) + ": ";
  if (!out.name) throw new Error(n + "enter the full name.");
  if (!out.line1 || !out.city) throw new Error(n + "enter the street address and city.");
  if (!US_STATES.includes(out.state)) throw new Error(n + "choose a US state.");
  if (!/^\d{5}(-\d{4})?$/.test(out.zip)) throw new Error(n + "enter a 5-digit ZIP code.");
  return out;
}

/* POST /account/profile { first_name?, last_name?, phone?, addresses?, subscribed? } — only the fields sent are changed. */
async function handleAccountProfile(request, env, cors) {
  if (!features(env).database) return json({ error: "Your account isn’t available right now." }, 501, cors);
  const s = await customerSession(request, env);
  if (!s) return signedOut(cors);
  const body = await readJson(request);
  const patch = {};
  if ("first_name" in body) patch.first_name = str(body.first_name, 60) || null;
  if ("last_name" in body) patch.last_name = str(body.last_name, 60) || null;
  if ("phone" in body) patch.phone = str(body.phone, 40) || null;
  if ("addresses" in body) {
    if (!Array.isArray(body.addresses) || body.addresses.length > 10) return json({ error: "You can save up to 10 addresses." }, 400, cors);
    try { patch.addresses = body.addresses.map(cleanAddress); } catch (e) { return json({ error: e.message }, 400, cors); }
    // Exactly one default (the first one if none was chosen).
    const d = Math.max(0, patch.addresses.findIndex((a) => a.is_default));
    patch.addresses.forEach((a, i) => { a.is_default = i === d; });
  }
  let profile = s.profile;
  if (Object.keys(patch).length) {
    const rows = await db(env, "customer_profiles?on_conflict=email", {
      method: "POST", headers: { Prefer: "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify(Object.assign({ email: s.email }, patch)),
    });
    profile = Array.isArray(rows) && rows[0] ? rows[0] : Object.assign({}, profile, patch);
  }
  let subscribed;
  if ("subscribed" in body) {
    if (body.subscribed) {
      await db(env, "subscribers?on_conflict=email", { method: "POST", headers: { Prefer: "resolution=ignore-duplicates" }, body: JSON.stringify({ email: s.email, source: "account" }) });
      subscribed = true;
    } else {
      await db(env, "subscribers?email=eq." + encodeURIComponent(s.email), { method: "DELETE" });
      subscribed = false;
    }
  }
  return json({ ok: true, profile: publicProfile(profile), subscribed }, 200, cors);
}

/* POST /account/signout-all — ends every session for this email (this one too). */
async function handleAccountSignoutAll(request, env, cors) {
  if (!features(env).database) return json({ error: "Not available right now." }, 501, cors);
  const s = await customerSession(request, env);
  if (!s) return signedOut(cors);
  await db(env, "customer_profiles?on_conflict=email", { method: "POST", headers: { Prefer: "resolution=merge-duplicates" }, body: JSON.stringify({ email: s.email, signed_out_at: new Date().toISOString() }) });
  return json({ ok: true }, 200, cors);
}

/* POST /account/delete — removes the profile, saved addresses and email sign-up, and ends every session.
   Orders stay (needed for taxes, returns and warranty), as the Privacy Policy explains. */
async function handleAccountDelete(request, env, cors) {
  if (!features(env).database) return json({ error: "Not available right now." }, 501, cors);
  const s = await customerSession(request, env);
  if (!s) return signedOut(cors);
  await Promise.all([
    db(env, "customer_profiles?on_conflict=email", {
      method: "POST", headers: { Prefer: "resolution=merge-duplicates" },
      body: JSON.stringify({ email: s.email, first_name: null, last_name: null, phone: null, addresses: [], signed_out_at: new Date().toISOString() }),
    }),
    db(env, "subscribers?email=eq." + encodeURIComponent(s.email), { method: "DELETE" }),
    db(env, "customer_login_codes?email=eq." + encodeURIComponent(s.email), { method: "DELETE" }),
  ]);
  return json({ ok: true }, 200, cors);
}

const RETURN_REASONS = ["Doesn’t fit or wrong size", "Not as described or pictured", "Arrived damaged or defective", "Wrong item sent", "Changed my mind", "Other"];
const RETURN_DAYS = 45; // from shipping; the policy gives 30 days from delivery

/* POST /account/return { order_number, reason, items: [index…], details } — asks us to take a shipped order back. */
async function handleAccountReturn(request, env, cors) {
  if (!features(env).database) return json({ error: "Returns can’t be requested here right now. Please contact us." }, 501, cors);
  const s = await customerSession(request, env);
  if (!s) return signedOut(cors);
  const body = await readJson(request);
  const number = String(body.order_number || "").trim().toUpperCase();
  if (!/^[A-Z]{2,4}-\d{1,12}$/.test(number)) return json({ error: "Order not found" }, 404, cors);
  if (!RETURN_REASONS.includes(body.reason)) return json({ error: "Choose a reason for the return." }, 400, cors);
  const order = await loadOrder(env, "order_number=eq." + encodeURIComponent(number) + "&email=eq." + encodeURIComponent(s.email));
  if (!order) return json({ error: "Order not found" }, 404, cors);
  if (order.return_requested_at) return json({ ok: true, already: true, return_requested_at: order.return_requested_at }, 200, cors);
  if (!/^(shipped|delivered)$/.test(order.status) || order.payment_status !== "paid") return json({ error: "This order can’t be returned here. Please contact us." }, 409, cors);
  const shipped = Date.parse(order.shipped_at || order.accepted_at || order.created_at);
  if (!(shipped > Date.now() - RETURN_DAYS * 86400000)) return json({ error: "The return window for this order has passed. Please contact us and we’ll see what we can do." }, 409, cors);
  const items = order.order_items || [];
  const picked = (Array.isArray(body.items) ? body.items : []).map(Number).filter((i) => Number.isInteger(i) && items[i]);
  if (!picked.length) return json({ error: "Choose at least one item to return." }, 400, cors);
  const names = [...new Set(picked)].map((i) => items[i].name + (items[i].variant ? " (" + items[i].variant + ")" : "") + " × " + items[i].qty);
  const text = ("Reason: " + body.reason + ". Items: " + names.join("; ") + "." + (str(body.details, 500) ? " Details: " + str(body.details, 500) : "")).slice(0, 1000);
  const rows = await patchOrder(env, "id=eq." + order.id + "&return_requested_at=is.null", { return_requested_at: new Date().toISOString(), return_reason: text });
  if (!Array.isArray(rows) || !rows.length) return json({ ok: true, already: true }, 200, cors);
  const fresh = Object.assign({}, order, rows[0]);
  await Promise.all([sendOrderEmail(env, "return", fresh, { items: names }), notifyStore(env, "Return requested: " + order.order_number, order.order_number + " (" + s.email + ")\n" + text + "\n\nOpen Admin › Orders to handle it.")]);
  return json({ ok: true, return_requested_at: fresh.return_requested_at }, 200, cors);
}

/* A plain note to the store's own contact email (Admin › Storefront). Never blocks the customer's request. */
async function notifyStore(env, subject, text) {
  if (!env.RESEND_API_KEY) return false;
  try {
    const data = await storeData(env);
    const to = env.EMAIL_REPLY_TO || (data.contact && data.contact.email);
    if (!to || !EMAIL_RE.test(to)) return false;
    const res = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json", "Idempotency-Key": "store-" + subject.replace(/[^\w-]/g, "").slice(0, 60) },
      body: JSON.stringify({ from: env.EMAIL_FROM || EMAIL_FROM_DEFAULT, to: [to], subject, text }),
    });
    if (!res.ok) console.error("store email failed", res.status);
    return res.ok;
  } catch (e) { console.error("store email failed", e && e.message); return false; }
}

/* ---------------------------------------------------------------- *
 * POST /order/placed { order_number, pay_token } — a cash-on-delivery order was just placed (card orders get this
 * email from the Stripe webhook instead). The pay token is only known to the browser that placed the order.
 * Sent once: Resend's idempotency key is the same as for the card flow.
 * ---------------------------------------------------------------- */
async function handleOrderPlaced(request, env, cors) {
  if (!features(env).database) return json({ ok: true }, 200, cors);
  const body = await readJson(request);
  const number = String(body.order_number || "").trim().toUpperCase();
  const token = String(body.pay_token || "");
  if (!/^[A-Z]{2,4}-\d{1,12}$/.test(number) || !UUID.test(token)) return json({ error: "Order not found" }, 404, cors);
  const order = await loadOrder(env, "order_number=eq." + encodeURIComponent(number) + "&pay_token=eq." + encodeURIComponent(token));
  if (!order) return json({ error: "Order not found" }, 404, cors);
  if (order.payment_method !== "cod" || order.status !== "new") return json({ ok: true, skipped: true }, 200, cors);
  if (Date.now() - Date.parse(order.created_at) > 3600000) return json({ ok: true, skipped: true }, 200, cors);
  await sendOrderEmail(env, "received", order);
  return json({ ok: true }, 200, cors);
}

/* ---------------------------------------------------------------- *
 * Rate limits for visitor forms: a keyed hash of the IP (never the IP itself) per bucket, kept a day.
 * ---------------------------------------------------------------- */
async function rateLimited(env, request, bucket, max, windowSec) {
  if (!features(env).database) return false;
  const key = hexOf(await hmacBytes(await accountKey(env), "rl:" + clientIp(request))).slice(0, 32);
  const since = encodeURIComponent(new Date(Date.now() - windowSec * 1000).toISOString());
  const rows = await db(env, "rate_hits?bucket=eq." + bucket + "&key=eq." + key + "&at=gt." + since + "&select=at&limit=" + max);
  if (Array.isArray(rows) && rows.length >= max) return true;
  await db(env, "rate_hits", { method: "POST", body: JSON.stringify({ bucket, key }) });
  if (Math.random() < 0.05) await db(env, "rate_hits?at=lt." + encodeURIComponent(new Date(Date.now() - 86400000).toISOString()), { method: "DELETE" }).catch(() => {});
  return false;
}

/* The signed "cancel" part of the link in the order email (only this server can make one). */
async function cancelToken(env, orderId) {
  return b64url(await hmacBytes(await accountKey(env), "cancel:" + orderId)).slice(0, 32);
}
async function cancelAllowed(request, env, order, body) {
  if (body.pay_token && UUID.test(String(body.pay_token)) && safeEqual(String(order.pay_token), String(body.pay_token))) return true;
  if (body.cancel_token && safeEqual(String(body.cancel_token), await cancelToken(env, order.id))) return true;
  if (/^Bearer\s/.test(request.headers.get("Authorization") || "")) {
    const s = await customerSession(request, env).catch(() => null);
    if (s && s.email === order.email) return true;
  }
  return false;
}

/* POST /order/status { order_number, pay_token } — lets the confirmation page check the payment instead of trusting the URL. */
async function handleOrderStatus(request, env, cors) {
  if (!features(env).database) return json({ error: "Not available" }, 501, cors);
  const body = await readJson(request);
  const number = String(body.order_number || "").trim().toUpperCase();
  const token = String(body.pay_token || "");
  if (!/^[A-Z]{2,4}-\d{1,12}$/.test(number) || !UUID.test(token)) return json({ error: "Order not found" }, 404, cors);
  const rows = await db(env, "orders?order_number=eq." + encodeURIComponent(number) + "&pay_token=eq." + encodeURIComponent(token) + "&select=status,payment_status,payment_method,paid_at,total&limit=1");
  const o = Array.isArray(rows) && rows[0];
  if (!o) return json({ error: "Order not found" }, 404, cors);
  return json({ ok: true, status: o.status, payment_status: o.payment_status, payment_method: o.payment_method, paid_at: o.paid_at, total: o.total }, 200, cors);
}

/* POST /account/signout — this session stops working everywhere, not just on this device. */
async function handleAccountSignout(request, env, cors) {
  if (!features(env).database) return json({ ok: true }, 200, cors);
  const s = await customerSession(request, env);
  if (s && s.nonce) {
    await db(env, "customer_revoked?on_conflict=n", { method: "POST", headers: { Prefer: "resolution=ignore-duplicates" }, body: JSON.stringify({ n: s.nonce.slice(0, 64), exp: new Date(s.exp * 1000).toISOString() }) }).catch(() => {});
    await db(env, "customer_revoked?exp=lt." + encodeURIComponent(new Date().toISOString()), { method: "DELETE" }).catch(() => {});
  }
  return json({ ok: true }, 200, cors);
}

/* ---------------------------------------------------------------- *
 * Visitor forms (were direct database calls; now rate-limited here). Errors keep the database's codes.
 * ---------------------------------------------------------------- */
const PUBLIC_LIMITS = { "/public/track": 30, "/public/cancel-request": 10, "/public/contact": 5, "/public/subscribe": 5, "/public/stock-alert": 10 };
async function handlePublic(path, request, env, cors) {
  if (!features(env).database) return json({ error: "Not available right now." }, 501, cors);
  const body = await readJson(request);
  if (path === "/public/contact" && str(body.website, 200)) return json({ ok: true }, 200, cors); // honeypot: pretend it worked
  if (await rateLimited(env, request, path.slice(8), PUBLIC_LIMITS[path], 3600)) return json({ error: "Too many tries. Please wait a while and try again.", code: "RATE_LIMIT" }, 429, cors);
  const rpc = (fn, args) => db(env, "rpc/" + fn, { method: "POST", body: JSON.stringify(args) });
  const email = String(body.email || "").trim().toLowerCase();
  const fail = (e) => {
    const code = (/(?:Database error \d+: )?([A-Z_]{4,40})/.exec(String(e && e.message)) || [])[1] || "ERROR";
    return json({ error: code, code }, code === "RATE_LIMIT" ? 429 : 400, cors);
  };
  if (path !== "/public/track" && path !== "/public/cancel-request" && !EMAIL_RE.test(email)) return json({ error: "INVALID_EMAIL", code: "INVALID_EMAIL" }, 400, cors);
  try {
    if (path === "/public/track") {
      const order = await rpc("track_order", { p_number: str(body.number, 20), p_email: str(body.email, 254) });
      return json({ ok: true, order: order || null }, 200, cors);
    }
    if (path === "/public/cancel-request") {
      return json(await rpc("request_cancel", { p_number: str(body.number, 20), p_email: str(body.email, 254), p_reason: str(body.reason, 500) }), 200, cors);
    }
    if (path === "/public/contact") {
      const name = str(body.name, 120), message = String(body.message == null ? "" : body.message).slice(0, 5000).trim();
      if (!name || !message) return json({ error: "Please fill in your name and message.", code: "INVALID" }, 400, cors);
      await db(env, "contact_messages", { method: "POST", body: JSON.stringify({ name, email, phone: str(body.phone, 40) || null, subject: str(body.subject, 200) || null, message }) });
      return json({ ok: true }, 200, cors);
    }
    if (path === "/public/subscribe") {
      return json(await rpc("subscribe", { p_email: email, p_source: str(body.source, 40) || "newsletter" }), 200, cors);
    }
    if (path === "/public/stock-alert") {
      return json(await rpc("request_stock_alert", { p_email: email, p_product_id: str(body.product_id, 80), p_sku: str(body.sku, 80), p_product_name: str(body.product_name, 300) }), 200, cors);
    }
  } catch (e) { return fail(e); }
  return json({ error: "Not found" }, 404, cors);
}


/* ---- Supabase Edge Function wrapper ---- */
const env = new Proxy({}, {
  get(_, key) {
    const k = String(key);
    const v = Deno.env.get(k);
    if (v !== undefined && v !== '') return v;
    if (k === 'SUPABASE_PUBLISHABLE_KEY') return Deno.env.get('SUPABASE_ANON_KEY');
    // Supabase doesn't allow secret names starting with SUPABASE_, so a manually added key uses this name.
    if (k === 'SUPABASE_SERVICE_ROLE_KEY') return Deno.env.get('SERVICE_ROLE_KEY');
    if (k === 'SELF_URL') return (Deno.env.get('SUPABASE_URL') || '').replace(/\/+$/, '') + '/functions/v1/hw';
    return undefined;
  },
});

Deno.serve((req) => {
  // The function sees its path as /hw/... (or /functions/v1/hw/...); the handler expects /... .
  const url = new URL(req.url);
  url.pathname = url.pathname.replace(/^\/(?:functions\/v1\/)?hw(?=\/|$)/, '') || '/';
  return handler.fetch(new Request(url.toString(), req), env);
});
